export const MOBILE_COURSE_HTML = Object.freeze({"autocad":"<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#14223a\"><title>Инженер с нуля · Мобильная академия</title>\n<style>\n:root{font:16px/1.5 system-ui,-apple-system,'Segoe UI',sans-serif;color:#20304a;background:#f1f4f9;--navy:#14223a;--accent:#2965e8;--muted:#5c6b80;--line:#dce3ed}*{box-sizing:border-box}body{margin:0;padding-bottom:100px}button,input{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #f0c55f}header{padding:20px max(18px,calc((100vw - 900px)/2));background:var(--navy);color:white}header small{color:#aebfdf}main{max-width:900px;margin:auto;padding:16px}h1{font-size:25px;line-height:1.15;margin:4px 0}h2{font-size:21px;margin:0 0 8px}h3{font-size:17px}.card{background:white;border:1px solid var(--line);border-radius:19px;padding:19px;margin-bottom:14px;box-shadow:0 3px 10px #192d4910}.muted{color:var(--muted);font-size:14px}.notice{background:#edf3ff;padding:12px;border-radius:12px;color:#274674;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.tile{padding:15px;border:1px solid var(--line);border-radius:13px;background:#fff;text-align:left}.tile b{display:block;font-size:22px}.tile small{color:var(--muted)}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:12px;background:var(--accent);color:#fff;padding:12px 15px;min-height:44px;font-weight:700}.btn.outline{background:#eef3ff;color:#2454ac}.btn.soft{background:#edf1f7;color:#20304a}.btn:disabled{opacity:.5}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.row>*{max-width:100%}.tabs{position:fixed;bottom:0;left:0;right:0;background:white;box-shadow:0 -4px 30px #15223a12;display:flex;justify-content:center;gap:3px;padding:9px 8px calc(10px + env(safe-area-inset-bottom));z-index:4}.tabs button{background:transparent;border:0;border-radius:10px;padding:8px 13px;font-weight:650;color:#58667d;font-size:12px}.tabs button.active{background:#eaf1ff;color:#1451c1}.days{display:grid;grid-template-columns:repeat(auto-fill,minmax(154px,1fr));gap:10px}.day{background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px;text-align:left}.day.done{border-color:#60aa89;background:#f0fff6}.day strong{display:block}.day small{display:block;color:var(--muted);font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.75 system-ui;max-height:450px;overflow:auto;padding:15px;border-radius:12px;background:#f6f8fb;border:1px solid #e7eaf0}details summary{font-weight:650;cursor:pointer;padding:8px 0}.bar{height:8px;border-radius:10px;background:#e4e8ef;overflow:hidden}.bar>div{height:100%;background:#2f75df}.field{display:block;width:100%;min-height:47px;border:1px solid #bac5d8;border-radius:10px;padding:10px;background:white;margin:10px 0}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border-bottom:1px solid var(--line);padding:8px;text-align:left}th{background:#f3f6fa}.scroll{overflow:auto}.pill{display:inline-block;background:#eaf1ff;padding:3px 8px;color:#2252a5;border-radius:999px;font-size:12px}.success{color:#137a4d;font-weight:750}.error{color:#ba2839;font-weight:750}#planchart{width:100%;min-height:125px}.tools button{border:1px solid #bdc8da;border-radius:12px;background:#fff;padding:7px 10px}#cad{width:100%;height:330px;border:1px solid #cad4e2;border-radius:14px;touch-action:none;background:#fbfdff}.stat{background:#eef3ff;border-radius:13px;padding:10px}.stat b{display:block}.full{width:100%}@media(max-width:420px){header{padding:16px}h1{font-size:22px}.card{padding:15px}.grid{grid-template-columns:1fr 1fr}.tabs button{font-size:11px;padding:7px}#cad{height:290px}}\n</style></head><body>\n<header><small>ИНЖЕНЕР С НУЛЯ · ОБУЧЕНИЕ НА ТЕЛЕФОНЕ</small><h1>Мобильная академия инженера</h1><small id=\"subhead\">AutoCAD · Primavera P6 · практические тренажёры</small></header>\n<main><div id=\"view\"></div></main><nav class=\"tabs\" id=\"tabs\"></nav>\n<script>\nconst COURSE_DATA={\"cad\":[{\"day\":1,\"title\":\"Старт: мобильный DWG\",\"goal\":\"Просмотр DWG/DXF, копия файла, безопасное управление видом\",\"explanation\":\"Открой учебный чертёж, сохрани отдельную копию; двумя пальцами измени масштаб, одним — перемести вид.\",\"challenge\":\"Укажи, почему исходник нельзя редактировать без копии.\",\"answer\":\"Редактирование копии сохраняет проверяемый оригинал.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Сделайте копию исходного файла до любого изменения; запишите имя, дату и единицы модели.\",\"mobileSteps\":\"Откройте схему и найдите два центра и четыре угла площадки.\",\"deliverable\":\"Скрин копии и запись исходной единицы измерения.\",\"pitfall\":\"В мобильном приложении набор редактируемых форматов зависит от уровня доступа.\"},{\"day\":2,\"title\":\"Типы объектов и свойства\",\"goal\":\"Слои, окружности, полилинии и их свойства\",\"explanation\":\"Выдели линию и окружность. Запиши слой, центр окружности и геометрический тип.\",\"challenge\":\"Чем окружность отличается от полилинии?\",\"answer\":\"Окружность имеет центр и радиус; полилиния — последовательность вершин.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Скрывайте слои по очереди, не удаляя их; сопоставьте объект, цвет, тип и свойства.\",\"mobileSteps\":\"Для двух линий и окружности составьте таблицу: объект / слой / размер.\",\"deliverable\":\"Три строки таблицы свойств.\",\"pitfall\":\"Цвет объекта не всегда однозначно указывает на его слой.\"},{\"day\":3,\"title\":\"Замеры на чертеже\",\"goal\":\"Длина, радиус, диаметр и угол\",\"explanation\":\"В чертеже-симуляторе измерь расстояние между двумя опорными точками; сравни с контрольными данными.\",\"challenge\":\"В каких единицах построена модель РВС-5000?\",\"answer\":\"В миллиметрах, в масштабе 1:1.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Проверьте масштаб геометрии по известному габариту; затем измерьте прямой отрезок.\",\"mobileSteps\":\"Запишите проектный диаметр резервуара и полученный замер.\",\"deliverable\":\"Таблица двух размеров и единицы мм.\",\"pitfall\":\"Длина на экране в пикселях не равна действительной длине в модели.\"},{\"day\":4,\"title\":\"Площадь и периметр\",\"goal\":\"Простые контуры, замкнутые границы\",\"explanation\":\"Определи площадь площадки 120×90 м и периметр.\",\"challenge\":\"Площадь площадки, м²\",\"answer\":10800,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Установите, замкнута ли граница; площадь разомкнутой полилинии ненадёжна.\",\"mobileSteps\":\"Вычислите площадь прямоугольника 120 м на 90 м и кольца как разность площадей кругов.\",\"deliverable\":\"Площадь площадки 10800 м²; список формул.\",\"pitfall\":\"Смешение мм² и м² создаёт ошибку масштаба в миллион раз.\"},{\"day\":5,\"title\":\"Координаты X/Y\",\"goal\":\"Проектные и фактические координаты\",\"explanation\":\"Найди проектный центр (60000;45000) и фактический (60018;44988) мм.\",\"challenge\":\"Отклонение центра по X, мм\",\"answer\":18,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"У координат есть порядок X/Y; проектные и фактические точки не смешивайте.\",\"mobileSteps\":\"Впишите фактический X и Y центра в журнал измерений, затем найдите приращения.\",\"deliverable\":\"ΔX=18 мм, ΔY=-12 мм.\",\"pitfall\":\"Отрицательное отклонение Y нельзя превращать в положительное.\"},{\"day\":6,\"title\":\"Точные геометрические построения\",\"goal\":\"Линия, круг, полилиния, привязка к координатам\",\"explanation\":\"В CAD-полигоне добавь точку и круг, используя координаты; сравни радиус основания.\",\"challenge\":\"Проектный радиус фундамента, мм\",\"answer\":12000,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Построение ведите в одной принятой системе единиц и координат.\",\"mobileSteps\":\"Создайте точку в учебном CAD-полигоне и сопоставьте номинальный радиус 12000 мм.\",\"deliverable\":\"Список созданных геометрических объектов.\",\"pitfall\":\"Рисовать от руки по визуальному масштабу недостаточно для исполнительных схем.\"},{\"day\":7,\"title\":\"Редактирование геометрии\",\"goal\":\"Перемещение, обрезка и исправление\",\"explanation\":\"Создай отдельную ревизию контура; измени положение учебной точки и сравни изменения.\",\"challenge\":\"Почему нельзя исправлять факт прямо на проектном слое?\",\"answer\":\"Смешение слоёв уничтожит возможность проверить отклонения.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"При правке одной геометрии сохраняйте исходник, новое состояние и причину правки.\",\"mobileSteps\":\"Обозначьте перемещённую точку и укажите величину сдвига по двум осям.\",\"deliverable\":\"Запись Rev A и скрин до/после.\",\"pitfall\":\"Изменение факта ради соответствия проекту недопустимо.\"},{\"day\":8,\"title\":\"Слои проект/факт\",\"goal\":\"Отдельные видимость и названия\",\"explanation\":\"Включи только проектный слой; затем только фактический. Оцени изменение положения центра.\",\"challenge\":\"Какой слой хранит измеренные координаты?\",\"answer\":\"Фактический (исполнительный) слой.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Создайте соглашение о названиях слоёв и отдельную таблицу видимости.\",\"mobileSteps\":\"По очереди выключите проект/факт в CAD-полигоне и запишите отличия.\",\"deliverable\":\"Два скрина с переключёнными слоями.\",\"pitfall\":\"Скрытый слой не означает, что его объектов нет в файле.\"},{\"day\":9,\"title\":\"Размеры и выноски\",\"goal\":\"Линейные и диаметральные размеры\",\"explanation\":\"Подготовь размерную выноску: X-факт, Y-факт, смещение центра и диаметр.\",\"challenge\":\"Отклонение центра по Y, мм\",\"answer\":-12,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Выноска должна показывать значение и единицу, а не только графический символ.\",\"mobileSteps\":\"Подпишите проектную и фактическую координату центра и посчитайте разность.\",\"deliverable\":\"Размерная таблица проекта и факта.\",\"pitfall\":\"Не считайте размерную надпись гарантией актуальности самой геометрии.\"},{\"day\":10,\"title\":\"Повторяющиеся элементы\",\"goal\":\"Блоки и 24 анкерных болта\",\"explanation\":\"На схеме размести болты по окружности, найди угловой шаг при 24 равномерно расположенных точках.\",\"challenge\":\"Угловой шаг болтов, градусы\",\"answer\":15,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Одинаковые элементы сначала типизируют, затем нумеруют и контролируют экземпляры.\",\"mobileSteps\":\"Разделите полный круг на 24 шага и оформите список первых четырёх углов.\",\"deliverable\":\"0°, 15°, 30°, 45°; всего 24 позиции.\",\"pitfall\":\"Полярное размещение условно, фактические замеры болтов индивидуальны.\"},{\"day\":11,\"title\":\"Листы и основная надпись\",\"goal\":\"Рамка A3 и реквизиты\",\"explanation\":\"Сформируй в мобильном блокноте титул: шифр объекта, номер листа, ревизию, дату и масштаб.\",\"challenge\":\"Какой формат листа выбран в учебном проекте?\",\"answer\":\"A3.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Лист и модель — разные представления. В основной надписи нужны идентификаторы документа.\",\"mobileSteps\":\"Заполните условный штамп A3, номер листа, дату, ревизию, обозначение учебного проекта.\",\"deliverable\":\"Электронный титульный блок.\",\"pitfall\":\"Неправильная ревизия разрушает трассируемость исполнительной документации.\"},{\"day\":12,\"title\":\"Масштаб и PDF\",\"goal\":\"Разница между моделью и листом\",\"explanation\":\"Проверь единицы модели 1:1 и целевой масштаб листа перед выпуском PDF.\",\"challenge\":\"Геометрию модели нужно уменьшать под лист?\",\"answer\":\"Нет, модель остаётся 1:1, масштаб задаётся в видовом экране/при печати.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Геометрию храните 1:1, масштаб выбирайте для печати, а не для исправления размеров.\",\"mobileSteps\":\"Проверьте на бумажном плане, читаются ли тексты и размеры при выбранном масштабе.\",\"deliverable\":\"Схема модели и выбранный масштаб листа.\",\"pitfall\":\"Не увеличивайте диаметр фактического фундамента ради красивого вывода.\"},{\"day\":13,\"title\":\"Внешние ссылки\",\"goal\":\"XREF и ссылочная целостность\",\"explanation\":\"Составь перечень всех файлов, на которые ссылается чертёж, проверь относительные пути.\",\"challenge\":\"Почему важно проверять потерянные ссылки?\",\"answer\":\"Пользователь может не увидеть часть исходной геометрии.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Внешняя ссылка зависит от местоположения исходного файла.\",\"mobileSteps\":\"Составьте список DWG, PDF и прочих подложек с относительными путями.\",\"deliverable\":\"Таблица ссылок, статуса загрузки и версии.\",\"pitfall\":\"Абсолютные пути с чужого ПК часто не работают.\"},{\"day\":14,\"title\":\"Логика исполнительной схемы\",\"goal\":\"Проект → Факт → Отклонение\",\"explanation\":\"Построй таблицу из проектной и фактической координаты, рассчитывая ΔX и ΔY.\",\"challenge\":\"Как вычислить ΔX?\",\"answer\":\"X факт минус X проект.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Исполнительная схема подтверждает измеренный факт, а не просто переносит проект.\",\"mobileSteps\":\"На четырёх точках сравните проектные/фактические координаты и зафиксируйте разницы.\",\"deliverable\":\"Таблица проект — факт — отклонение.\",\"pitfall\":\"Без даты измерения и основания нельзя утверждать фактическое положение.\"},{\"day\":15,\"title\":\"Схема фундамента\",\"goal\":\"Смещение центра, диаметры и отметки\",\"explanation\":\"Выполни расчёт смещения центра по результатам измерений (18 мм; −12 мм).\",\"challenge\":\"Модуль смещения центра, мм (2 знака)\",\"answer\":21.63,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Смещение в плане считайте как геометрическую длину вектора отклонения.\",\"mobileSteps\":\"По (ΔX;ΔY)=(18;-12) мм найдите √(18²+12²) и округлите до сотых.\",\"deliverable\":\"21,63 мм и показанные промежуточные вычисления.\",\"pitfall\":\"Учебный допуск нельзя выдавать за нормативный допуск строительства.\"},{\"day\":16,\"title\":\"Анкерные болты\",\"goal\":\"Нумерация и таблица отклонений\",\"explanation\":\"Составь журнал 24 анкеров: номер, номинальный угол, фактическое смещение, оценка по условным правилам.\",\"challenge\":\"Количество анкеров\",\"answer\":24,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Каждому болту нужен свой идентификатор; общий круг — лишь проектный ориентир.\",\"mobileSteps\":\"Сформируйте таблицу болтов Б01–Б24 и углов с шагом 15°.\",\"deliverable\":\"24 уникальных номера, первый угол 0°, последний 345°.\",\"pitfall\":\"Проверка одного болта не заменяет проверку всех 24.\"},{\"day\":17,\"title\":\"Площадка и дорога\",\"goal\":\"Поперечные размеры и координаты углов\",\"explanation\":\"На базе учебной площадки найди два габаритных размера и зафиксируй фактический замер.\",\"challenge\":\"Длина площадки, м\",\"answer\":120,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Проверяйте габариты, положение осей и привязку к координатной основе.\",\"mobileSteps\":\"Выпишите габариты 120×90 м, площадь, четыре вершины учебной площадки.\",\"deliverable\":\"Четыре пары координат и габаритный контроль.\",\"pitfall\":\"Длину в мм нельзя писать в отчёте как метры без пересчёта.\"},{\"day\":18,\"title\":\"Ось трубопровода\",\"goal\":\"Изломы, отметки, длины\",\"explanation\":\"Создай полилинию по заданным точкам и рассчитай сумму длин её отрезков.\",\"challenge\":\"Как считается общая длина полилинии?\",\"answer\":\"Сумма длин всех последовательных сегментов.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Длину ломаной считают по сегментам, а не только по расстоянию между крайними точками.\",\"mobileSteps\":\"Постройте маршрут из трёх узлов, сложите длины двух звеньев.\",\"deliverable\":\"Координаты точек, две длины, итог.\",\"pitfall\":\"Прямая между началом и концом часто короче трассы.\"},{\"day\":19,\"title\":\"Ревизии и redline\",\"goal\":\"Журнал изменений и согласования\",\"explanation\":\"Заполни запись Rev B: причина, затронутые листы, дата, статус согласования.\",\"challenge\":\"Зачем хранить журнал ревизий?\",\"answer\":\"Чтобы проследить, кем, когда и почему изменена документация.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Каждая ревизия должна иметь входное изменение и указание затронутых листов.\",\"mobileSteps\":\"Составьте карточку изменения: инициатор, причина, объект, проверка, согласование.\",\"deliverable\":\"Rev A/B и таблица затронутых работ.\",\"pitfall\":\"Без фиксации изменения невозможно доказать актуальность листа.\"},{\"day\":20,\"title\":\"Контроль качества\",\"goal\":\"Дубли, разрывы, слои, единицы\",\"explanation\":\"Пройди 7 контрольных пунктов: открытие, координаты, единицы, слои, размеры, ссылки, оформление.\",\"challenge\":\"Что проверяют перед выпуском документации?\",\"answer\":\"Геометрию, единицы, полноту ссылок, реквизиты, согласования и ревизии.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Контроль качества охватывает геометрию, документы, оформление и след ссылок.\",\"mobileSteps\":\"Выполните контрольный лист из семи пунктов; отметьте замечание и ответственного.\",\"deliverable\":\"QA-лист, 7 проверок, исправленные замечания.\",\"pitfall\":\"Автоматическая очистка может удалить нужные объекты — делайте копию.\"},{\"day\":21,\"title\":\"Итоговый проект\",\"goal\":\"Исполнительная схема и портфолио\",\"explanation\":\"Собери учебный отчёт: схему, таблицу проект/факт, ΔX, ΔY, итоговый расчёт, титул и журнал изменений.\",\"challenge\":\"Смещение центра в мм, до 2 знаков\",\"answer\":21.63,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"В портфолио включайте только собственный учебный результат и пояснение расчётов.\",\"mobileSteps\":\"Соберите 1 лист A3, таблицу отклонений, журнал изменений и краткую защиту.\",\"deliverable\":\"Итоговая учебная исполнительная схема, PDF и отчёт.\",\"pitfall\":\"Учебный пример не подтверждает соответствие реального объекта нормативам.\"}],\"p6\":[]};\nconst PRODUCT_MODE='cad';let DATA=COURSE_DATA;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>\"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[x]));\nlet state={section:'home',course:'cad',day:1};let completed=(()=>{try{return JSON.parse(localStorage.getItem('izn_progress_v1')||'{}')}catch{return {}}})();\nfunction save(){try{localStorage.setItem('izn_progress_v1',JSON.stringify(completed))}catch{}}const days=id=>DATA[id]||[];\nfunction render(){const links=[['home','Обзор'],['cad','AutoCAD'],['p6','Primavera'],['drawing','Чертёж'],['schedule','График']].filter(([id])=>PRODUCT_MODE==='all'||(PRODUCT_MODE==='cad'?['home','cad','drawing'].includes(id):['home','p6','schedule'].includes(id)));$('#tabs').innerHTML=links.map(([id,label])=>`<button data-go=\"${id}\" class=\"${state.section===id?'active':''}\">${label}</button>`).join('');\nif(state.section==='home')home();else if(['cad','p6'].includes(state.section))course(state.section);else if(state.section==='lesson')lesson();else if(state.section==='drawing')drawing();else if(state.section==='schedule')schedule();}\nfunction home(){let c=Object.keys(completed).filter(k=>completed[k]&&(PRODUCT_MODE==='all'||k.startsWith(PRODUCT_MODE))).length;const TOTAL=Object.values(DATA).reduce((a,x)=>a+x.length,0);$('#view').innerHTML=`<section class=\"card\"><h2>Учись, выполняй и проверяй</h2><p>Полноценный мобильный учебник с самостоятельными заданиями. Данные сохраняются на устройстве. Все числовые примеры — условный учебный проект РВС-5000.</p><div class=\"grid\"><button class=\"tile\" data-go=\"cad\"><b>21 день</b>AutoCAD<br><small>DWG, размеры, проект/факт</small></button><button class=\"tile\" data-go=\"p6\"><b>14 дней</b>Primavera P6<br><small>WBS, CPM, baseline, план-факт</small></button></div><p class=\"muted\">Пройдено уроков: <b>${c} / ${TOTAL}</b></p><div class=\"bar\"><div style=\"width:${Math.round(c/Math.max(TOTAL,1)*100)}%\"></div></div></section><section class=\"card\"><h2>Работа прямо на телефоне</h2><div class=\"row\"><button class=\"btn outline\" data-go=\"drawing\">Открыть CAD-практику</button><button class=\"btn outline\" data-go=\"schedule\">Открыть CPM-график</button></div><p class=\"notice\">Тренажёры выполняют учебные вычисления и не являются программами Autodesk или Oracle. AutoCAD Mobile / Primavera требуют собственных прав доступа и лицензий.</p></section>`;if(PRODUCT_MODE==='cad')document.querySelectorAll('[data-go=\"p6\"],[data-go=\"schedule\"]').forEach(x=>x.remove());if(PRODUCT_MODE==='p6')document.querySelectorAll('[data-go=\"cad\"],[data-go=\"drawing\"]').forEach(x=>x.remove())}\nfunction course(id){if(PRODUCT_MODE!=='all'&&id!==PRODUCT_MODE)return home();state.course=id;let a=days(id),c=a.filter(x=>completed[id+x.day]).length;$('#view').innerHTML=`<section class=\"card\"><h2>${id==='cad'?'AutoCAD · 21 день':'Primavera P6 · 14 дней'}</h2><p class=\"muted\">${id==='cad'?'Мобильная адаптация курса по исполнительной документации':'Полный текст 14-дневного курса P6 Professional с мобильными тренировками'}</p><div class=\"bar\"><div style=\"width:${Math.round(c/a.length*100)}%\"></div></div><p>${c} из ${a.length} дней завершено</p></section><section class=\"days\">${a.map(x=>`<button class=\"day ${completed[id+x.day]?'done':''}\" data-lesson=\"${id}:${x.day}\"><strong>${completed[id+x.day]?'✓ ':''}День ${x.day}</strong><small>${esc(x.title)}</small></button>`).join('')}</section>`;}\nfunction lesson(){let a=days(state.course),x=a.find(l=>l.day===state.day);if(!x){state.section=state.course;return render()};let value=completed[state.course+x.day];$('#view').innerHTML=`<div class=\"row\" style=\"margin-bottom:12px\"><button class=\"btn soft\" data-go=\"${state.course}\">← К дням</button><span class=\"pill\">День ${x.day}/${a.length}</span></div><section class=\"card\"><h2>${esc(x.title)}</h2><p>${esc(x.goal)}</p>${state.course==='p6'?`<p class=\"notice\">${esc(x.phoneTip)}</p><details><summary>Полный материал урока · читать</summary><pre>${esc(x.full)}</pre></details>`:`<h3>Что важно понять</h3><p>${esc(x.concept)}</p><h3>Практика на телефоне</h3><p>${esc(x.explanation)}</p><p>${esc(x.mobileSteps)}</p><h3>Контрольный результат</h3><p>${esc(x.deliverable)}</p><div class=\"notice\">Частая ошибка: ${esc(x.pitfall)}. Возможности Autodesk AutoCAD Mobile могут отличаться от Windows.</div>`}<div class=\"row\"><button class=\"btn outline\" data-go=\"${state.course==='cad'?'drawing':'schedule'}\">Открыть учебный инструмент</button><button class=\"btn soft\" data-action=\"speak\">Прослушать</button></div></section><section class=\"card\"><h2>Проверка урока</h2><p>${esc(x.challenge)}</p><input id=\"checkanswer\" class=\"field\" placeholder=\"${x.answerType==='number'?'Введите результат числом':'Запишите краткий ответ'}\" inputmode=\"${x.answerType==='number'?'decimal':'text'}\"><div class=\"row\"><button class=\"btn\" data-action=\"check\">Проверить</button><button class=\"btn soft\" data-action=\"showAnswer\">Показать разбор</button></div><div id=\"feedback\" style=\"margin:12px 0\"></div><button class=\"btn outline full\" data-action=\"done\">${value?'✓ Урок пройден · подтвердить':'Отметить выполнение практики'}</button><p class=\"muted\">Отметка урока означает самостоятельное выполнение. Знание программы не подтверждается официальным сертификатом.</p></section>`;}\nfunction check(){let x=days(state.course).find(l=>l.day===state.day),u=$('#checkanswer').value.trim();let answer=x.answer;let okay=x.answerType==='number'?u!==''&&Math.abs(Number(u.replace(',','.'))-Number(answer))<.03:u.length>5;$('#feedback').innerHTML=`<div class=\"${okay?'success':'error'}\">${okay?'Ответ принят для учебного упражнения.':'Нужно ещё проверить решение или прочитать разбор.'}</div>${x.answerType==='text'?'Для текстового вопроса здесь проверяется только заполнение ответа. Содержание сравните с эталоном; автоматическая смысловая проверка не выполняется.':''}`;}\nfunction showAnswer(){let x=days(state.course).find(l=>l.day===state.day);$('#feedback').innerHTML=`<div class=\"notice\">Учебный эталон: <b>${esc(x.answer)}</b></div>`}\nfunction done(){completed[state.course+state.day]=true;save();let d=state.day;state.day=Math.min(days(state.course).length,d+1);render()}\nfunction speak(){let x=days(state.course).find(l=>l.day===state.day);if(!('speechSynthesis'in window))return alert('На этом устройстве синтез речи не поддерживается');speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance([x.title,x.goal,x.explanation||x.full?.slice(0,1200)||''].join('. '));utterance.lang='ru-RU';speechSynthesis.speak(utterance)}\n// Coordinate-based educational drawing (not DWG editor)\nlet cad={scale:1,ox:0,oy:0,tool:'pan',layers:{project:true,fact:true,point:true},points:[],drag:null};\nfunction drawing(){let key='cad';$('#view').innerHTML=`<section class=\"card\"><h2>CAD-полигон · РВС-5000</h2><p class=\"muted\">Проект: (60000;45000) мм · факт: (60018;44988) мм. Схема намеренно увеличивает отклонение, чтобы его было видно.</p><div class=\"row tools\"><button data-cad=\"pan\">Перемещение</button><button data-cad=\"point\">Точка</button><button data-cad=\"measure\">Измерение</button><button data-cad=\"zoom+\">＋</button><button data-cad=\"zoom-\">－</button><button data-cad=\"reset\">Сброс</button></div><p><label><input id=\"cadproject\" type=\"checkbox\" checked> Проект</label> · <label><input id=\"cadfact\" type=\"checkbox\" checked> Факт</label></p><canvas id=\"cad\" width=\"800\" height=\"500\" aria-label=\"Схема площадки РВС-5000\"></canvas><p id=\"cadout\" class=\"notice\">Касание с выбранным инструментом.</p><div class=\"row\"><button class=\"btn outline\" data-action=\"cadexport\">Экспорт точек DXF</button><button class=\"btn soft\" data-action=\"cadreport\">Скачать отчёт</button></div></section>`;paintCad();}\nfunction cv(){return $('#cad')?.getContext('2d')}const tx=(x,w)=>w/2+(x-60000)/350*cad.scale+cad.ox,ty=(y,h)=>h/2-(y-45000)/350*cad.scale+cad.oy;\nfunction paintCad(){const ctx=cv();if(!ctx)return;const w=800,h=500;ctx.clearRect(0,0,w,h);ctx.fillStyle='#fbfdff';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#e6edf4';for(let i=0;i<w;i+=40){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,h);ctx.stroke()}for(let j=0;j<h;j+=40){ctx.beginPath();ctx.moveTo(0,j);ctx.lineTo(w,j);ctx.stroke()}function ring(x,y,r,col){ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(tx(x,w),ty(y,h),r/350*cad.scale,r/350*cad.scale,0,0,2*Math.PI);ctx.stroke()}\nif(cad.layers.project){ring(60000,45000,12000,'#346ce8');ring(60000,45000,11000,'#4e7ef2');ctx.fillStyle='#346ce8';ctx.fillText('Проект: 60000, 45000',20,26)}if(cad.layers.fact){ring(60018+700,44988-450,12007,'#e38432');ctx.fillStyle='#9f5700';ctx.fillText('Факт: +18 / -12 мм (графически увеличено)',20,47)}ctx.fillStyle='#1e855e';for(let p of cad.points){ctx.beginPath();ctx.arc(tx(p.x,w),ty(p.y,h),4,0,7);ctx.fill()}ctx.font='17px system-ui';ctx.fillStyle='#435875';ctx.fillText('Учебный чертёж · не геодезическая основа',20,h-18)}\nfunction cadInteraction(evt){if(!$('#cad'))return;const rect=$('#cad').getBoundingClientRect();let px=(evt.clientX-rect.left)*800/rect.width,py=(evt.clientY-rect.top)*500/rect.height;let x=60000+((px-400-cad.ox)*350/cad.scale),y=45000-((py-250-cad.oy)*350/cad.scale);if(cad.tool==='point'){cad.points.push({x:Math.round(x),y:Math.round(y)});$('#cadout').textContent='Добавлена точка ('+Math.round(x)+'; '+Math.round(y)+') мм'}else if(cad.tool==='measure'){let p=cad.measure;if(!p){cad.measure={x,y};$('#cadout').textContent='Выберите вторую точку'}else{let dist=Math.hypot(x-p.x,y-p.y);$('#cadout').textContent='Учебная длина: '+dist.toFixed(1)+' мм';cad.measure=null}}paintCad()}\nfunction fileDownload(name,content,mime){const blob=new Blob([content],{type:mime||'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}\nfunction cadExport(){let lines=['0','SECTION','2','ENTITIES'];for(const p of cad.points){lines.push('0','POINT','8','IZN_USER_POINTS','10',String(p.x),'20',String(p.y),'30','0')}lines.push('0','ENDSEC','0','EOF');fileDownload('IZN_учебные_точки.dxf',lines.join('\\n'),'application/dxf')}\n// Editable, mathematically validated basic CPM in working-day units, NOT a full P6 scheduler.\nlet jobs=[{id:'ENG',name:'Проектирование',d:4,p:''},{id:'PRC',name:'Поставка',d:7,p:'ENG'},{id:'CIV',name:'Основание',d:6,p:'ENG'},{id:'MEC',name:'Монтаж',d:5,p:'PRC,CIV'},{id:'TST',name:'Испытания',d:3,p:'MEC'}];let baseline=null;\nfunction cpm(input=jobs){const dict=Object.fromEntries(input.map(x=>[x.id,{...x,prev:x.p.split(',').map(t=>t.trim()).filter(Boolean),ES:0,EF:0,LS:0,LF:0,TF:0}]));if(Object.keys(dict).length!==input.length)throw Error('Повтор Activity ID.');for(const x of Object.values(dict))for(const p of x.prev)if(!dict[p])throw Error('Неизвестная предшествующая операция: '+p);let order=[],seen=new Set();while(order.length<input.length){let ready=Object.values(dict).filter(x=>!seen.has(x.id)&&x.prev.every(p=>seen.has(p)));if(!ready.length)throw Error('Цикл в связях — исправьте предшественников');for(const x of ready){x.ES=x.prev.length?Math.max(...x.prev.map(p=>dict[p].EF)):0;x.EF=x.ES+x.d;if(!(x.d>=0&&Number.isFinite(x.d)))throw Error('Длительность должна быть неотрицательной');order.push(x);seen.add(x.id)}}let duration=Math.max(...order.map(x=>x.EF));for(let i=order.length-1;i>=0;i--){let x=order[i],succ=order.filter(s=>s.prev.includes(x.id));x.LF=succ.length?Math.min(...succ.map(s=>s.LS)):duration;x.LS=x.LF-x.d;x.TF=x.LS-x.ES}return {order,duration}}\nfunction schedule(){let out;try{out=cpm()}catch(e){out={error:e.message}}$('#view').innerHTML=`<section class=\"card\"><h2>CPM-лаборатория · критический путь</h2><p class=\"muted\">Редактируйте длительности и предшественников FS, пересчитывайте ранние и поздние сроки и резервы. Это учебная модель с единым условным календарём, не Oracle P6.</p><div class=\"scroll\"><table><thead><tr><th>ID</th><th>Работа</th><th>Дней</th><th>Предш.</th><th>ES</th><th>EF</th><th>TF</th></tr></thead><tbody>${jobs.map((j,i)=>`<tr><td>${esc(j.id)}</td><td>${esc(j.name)}</td><td><input data-job=\"${i}\" data-key=\"d\" type=\"number\" min=\"0\" step=\"1\" value=\"${j.d}\" style=\"width:60px\"></td><td><input data-job=\"${i}\" data-key=\"p\" value=\"${esc(j.p)}\" style=\"width:90px\"></td><td>${out.error?'—':out.order.find(x=>x.id===j.id).ES}</td><td>${out.error?'—':out.order.find(x=>x.id===j.id).EF}</td><td>${out.error?'—':out.order.find(x=>x.id===j.id).TF}</td></tr>`).join('')}</tbody></table></div><p class=\"${out.error?'error':'success'}\">${out.error?esc(out.error):'Длительность проекта: '+out.duration+' раб. дней · Критические работы: '+out.order.filter(x=>x.TF===0).map(x=>x.id).join(' → ')}</p><div class=\"row\"><button class=\"btn\" data-action=\"calc\">Пересчитать</button><button class=\"btn outline\" data-action=\"baseline\">Зафиксировать baseline</button><button class=\"btn soft\" data-action=\"report\">Отчёт</button></div>${baseline!==null?`<p class=\"notice\">Baseline: ${baseline} дней. Отклонение нового прогноза: ${out.error?'—':out.duration-baseline} дней.</p>`:''}</section>`}\nfunction updateJobs(){document.querySelectorAll('[data-job]').forEach(n=>{let j=jobs[Number(n.dataset.job)];j[n.dataset.key]=n.dataset.key==='d'?Number(n.value):n.value.toUpperCase().trim()})}\nfunction report(){let r;try{r=cpm()}catch(e){return alert(e.message)}fileDownload('RVS5000_CPM_отчёт.csv',['ID;Работа;Дней;Предшественники;ES;EF;LS;LF;TF',...r.order.map(x=>[x.id,x.name,x.d,x.prev.join(','),x.ES,x.EF,x.LS,x.LF,x.TF].join(';'))].join('\\n'),'text/csv;charset=utf-8')}\ndocument.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let go=b.dataset.go,les=b.dataset.lesson,action=b.dataset.action,mode=b.dataset.cad;if(go){state.section=go;render();scrollTo(0,0)}if(les){let[id,day]=les.split(':');state={section:'lesson',course:id,day:Number(day)};render();scrollTo(0,0)}if(mode){if(mode==='zoom+')cad.scale*=1.3;else if(mode==='zoom-')cad.scale/=1.3;else if(mode==='reset')cad={scale:1,ox:0,oy:0,tool:'pan',layers:{project:true,fact:true,point:true},points:[]};else cad.tool=mode;paintCad()}if(action==='check')check();if(action==='showAnswer')showAnswer();if(action==='done')done();if(action==='speak')speak();if(action==='cadexport')cadExport();if(action==='cadreport')fileDownload('RVS5000_измерения.txt',`Проект: X=60000 Y=45000 мм\\nФакт: X=60018 Y=44988 мм\\nСмещение: 21.63 мм\\nСозданные точки: ${JSON.stringify(cad.points)}`);if(action==='calc'){updateJobs();schedule()}if(action==='baseline'){updateJobs();try{baseline=cpm().duration;schedule()}catch(e){alert(e.message)}}if(action==='report'){updateJobs();report()}});\ndocument.addEventListener('change',e=>{if(e.target.id==='cadproject'){cad.layers.project=e.target.checked;paintCad()}if(e.target.id==='cadfact'){cad.layers.fact=e.target.checked;paintCad()}});\ndocument.addEventListener('pointerdown',e=>{if(e.target.id!=='cad')return;if(cad.tool!=='pan')return;cad.drag={x:e.clientX,y:e.clientY,ox:cad.ox,oy:cad.oy};e.target.setPointerCapture(e.pointerId)});\ndocument.addEventListener('pointermove',e=>{if(e.target.id!=='cad'||!cad.drag)return;const r=$('#cad').getBoundingClientRect();cad.ox=cad.drag.ox+(e.clientX-cad.drag.x)*800/r.width;cad.oy=cad.drag.oy+(e.clientY-cad.drag.y)*500/r.height;paintCad()});\ndocument.addEventListener('pointerup',e=>{if(e.target.id!=='cad')return;if(cad.drag){cad.drag=null;return}cadInteraction(e)});render();\n</script></body></html>","primavera":"<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#14223a\"><title>Инженер с нуля · Мобильная академия</title>\n<style>\n:root{font:16px/1.5 system-ui,-apple-system,'Segoe UI',sans-serif;color:#20304a;background:#f1f4f9;--navy:#14223a;--accent:#2965e8;--muted:#5c6b80;--line:#dce3ed}*{box-sizing:border-box}body{margin:0;padding-bottom:100px}button,input{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #f0c55f}header{padding:20px max(18px,calc((100vw - 900px)/2));background:var(--navy);color:white}header small{color:#aebfdf}main{max-width:900px;margin:auto;padding:16px}h1{font-size:25px;line-height:1.15;margin:4px 0}h2{font-size:21px;margin:0 0 8px}h3{font-size:17px}.card{background:white;border:1px solid var(--line);border-radius:19px;padding:19px;margin-bottom:14px;box-shadow:0 3px 10px #192d4910}.muted{color:var(--muted);font-size:14px}.notice{background:#edf3ff;padding:12px;border-radius:12px;color:#274674;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.tile{padding:15px;border:1px solid var(--line);border-radius:13px;background:#fff;text-align:left}.tile b{display:block;font-size:22px}.tile small{color:var(--muted)}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:12px;background:var(--accent);color:#fff;padding:12px 15px;min-height:44px;font-weight:700}.btn.outline{background:#eef3ff;color:#2454ac}.btn.soft{background:#edf1f7;color:#20304a}.btn:disabled{opacity:.5}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.row>*{max-width:100%}.tabs{position:fixed;bottom:0;left:0;right:0;background:white;box-shadow:0 -4px 30px #15223a12;display:flex;justify-content:center;gap:3px;padding:9px 8px calc(10px + env(safe-area-inset-bottom));z-index:4}.tabs button{background:transparent;border:0;border-radius:10px;padding:8px 13px;font-weight:650;color:#58667d;font-size:12px}.tabs button.active{background:#eaf1ff;color:#1451c1}.days{display:grid;grid-template-columns:repeat(auto-fill,minmax(154px,1fr));gap:10px}.day{background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px;text-align:left}.day.done{border-color:#60aa89;background:#f0fff6}.day strong{display:block}.day small{display:block;color:var(--muted);font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.75 system-ui;max-height:450px;overflow:auto;padding:15px;border-radius:12px;background:#f6f8fb;border:1px solid #e7eaf0}details summary{font-weight:650;cursor:pointer;padding:8px 0}.bar{height:8px;border-radius:10px;background:#e4e8ef;overflow:hidden}.bar>div{height:100%;background:#2f75df}.field{display:block;width:100%;min-height:47px;border:1px solid #bac5d8;border-radius:10px;padding:10px;background:white;margin:10px 0}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border-bottom:1px solid var(--line);padding:8px;text-align:left}th{background:#f3f6fa}.scroll{overflow:auto}.pill{display:inline-block;background:#eaf1ff;padding:3px 8px;color:#2252a5;border-radius:999px;font-size:12px}.success{color:#137a4d;font-weight:750}.error{color:#ba2839;font-weight:750}#planchart{width:100%;min-height:125px}.tools button{border:1px solid #bdc8da;border-radius:12px;background:#fff;padding:7px 10px}#cad{width:100%;height:330px;border:1px solid #cad4e2;border-radius:14px;touch-action:none;background:#fbfdff}.stat{background:#eef3ff;border-radius:13px;padding:10px}.stat b{display:block}.full{width:100%}@media(max-width:420px){header{padding:16px}h1{font-size:22px}.card{padding:15px}.grid{grid-template-columns:1fr 1fr}.tabs button{font-size:11px;padding:7px}#cad{height:290px}}\n</style></head><body>\n<header><small>ИНЖЕНЕР С НУЛЯ · ОБУЧЕНИЕ НА ТЕЛЕФОНЕ</small><h1>Мобильная академия инженера</h1><small id=\"subhead\">AutoCAD · Primavera P6 · практические тренажёры</small></header>\n<main><div id=\"view\"></div></main><nav class=\"tabs\" id=\"tabs\"></nav>\n<script>\nconst COURSE_DATA={\"cad\":[],\"p6\":[{\"day\":1,\"title\":\"День 1. Среда P6, единицы измерения и структура данных Цель дня. Понимать, где в P6 находятся EPS, OBS, Projects, WBS и Activities; настроит\",\"goal\":\"Понимать, где в P6 находятся EPS, OBS, Projects, WBS и Activities; настроить отображение дат и длительностей.\",\"full\":\"День 1. Среда P6, единицы измерения и структура\\nданных\\n  Цель дня. Понимать, где в P6 находятся EPS, OBS, Projects, WBS и Activities; настроить\\n  отображение дат и длительностей.\\n\\nЧто нужно понять\\n  EPS - иерархия портфеля и проектов. OBS - ответственность и доступ. Project - контейнер графика. WBS -\\n   декомпозиция результата. Activity - планируемая работа или веха.\\n  Data Date разделяет фактическое прошлое и прогнозное будущее. Planned Start не заменяет корректный\\n   CPM-расчет.\\n  До ввода данных закрепите единицы: часы в дне, дни в неделе, формат дат, валюту и локальные\\n   настройки.\\n\\nПрактика в P6\\n1. Откройте P6 и сохраните отдельный учебный layout.\\n2. Проверьте User Preferences: Time Units, Dates, Currency, Assistance.\\n3. Создайте EPS-узел TRAINING и проект RVS5000-TRN с Planned Start 07.09.2026 08:00.\\n4. Назначьте Data Date равной старту проекта.\\n\\nКонтроль результата\\n  Доказательство. Скрин проекта в Projects и окно Activities с колонками Activity ID, Name, Original\\n  Duration, Start, Finish, Total Float.\\n\\n  Типичная ошибка. Начинать ввод операций, не проверив часы/день и формат календаря: затем\\n  длительности и трудозатраты выглядят неправильно.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Выберите корректную иерархию данных.\",\"answer\":\"EPS → Project → WBS → Activity\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":2,\"title\":\"День 2. Календари: офис, площадка, смена и непрерывные процессы Цель дня. Создать четыре календаря проекта и понять, как календарь меняет да\",\"goal\":\"Создать четыре календаря проекта и понять, как календарь меняет дату окончания.\",\"full\":\"День 2. Календари: офис, площадка, смена и\\nнепрерывные процессы\\n  Цель дня. Создать четыре календаря проекта и понять, как календарь меняет дату окончания.\\n\\nЧто нужно понять\\n  Календарь определяет рабочие интервалы, выходные и исключения. Одинаковые «5 дней» на 5x8 и 7x12\\n   заканчиваются в разные даты.\\n  Для проекта используются CAL-5X8, CAL-6X10, CAL-7X12 и CAL-24X7. Непрерывный календарь применен\\n   только там, где процесс действительно не прерывается.\\n  Не маскируйте ускорение изменением Hours/Day. Смена календаря - управленческое решение, которое\\n   должно быть видно в графике.\\n\\nПрактика в P6\\n1. Создайте календари по листу Calendars мастер-файла.\\n2. Добавьте праздники и проверьте рабочие интервалы в Workweek и Exceptions.\\n3. Создайте четыре тестовые операции по 5 дней на разных календарях и выполните F9.\\n4. Сравните Start/Finish и удалите тестовые операции.\\n\\nКонтроль результата\\n  Доказательство. Четыре календаря и краткая таблица сравнения окончания тестовых операций.\\n\\n  Типичная ошибка. Назначать 24x7 всем работам ради ранней даты. Это создает нереалистичный\\n  прогноз и скрывает потребность в сменах.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"При разных календарях 5 дней означают одинаковую календарную длительность?\",\"answer\":\"Нет, результат зависит от рабочего календаря.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":3,\"title\":\"День 3. WBS, Activity ID и кодирование графика Цель дня. Создать управляемую WBS и правила идентификации операций.\",\"goal\":\"Создать управляемую WBS и правила идентификации операций.\",\"full\":\"День 3. WBS, Activity ID и кодирование графика\\n  Цель дня. Создать управляемую WBS и правила идентификации операций.\\n\\nЧто нужно понять\\n  WBS отвечает на вопрос «какой результат/часть объекта», а Activity Code - «какой тип, дисциплина, фронт\\n   или пакет». Не превращайте WBS в список исполнителей.\\n  Activity ID должен быть уникальным, коротким и стабильным. В проекте применены префиксы PM, ENG,\\n   PRC, MOB, CIV, FAB, ERT, MEC, ELC, COA, TST, HND.\\n  Для фильтров нужны коды Discipline, Phase, Area, Workfront, Contract Package и Responsible.\\n\\nПрактика в P6\\n1. Создайте корень RVS5000 и 12 дочерних WBS по мастер-файлу.\\n2. Создайте проектные Activity Codes: Discipline, Phase, Area, Workfront, Contract Package.\\n3. Создайте первые 20 операций вручную, соблюдая Activity ID.\\n4. Сгруппируйте Activities по WBS и сохраните layout RVS_01_WBS.\\n\\nКонтроль результата\\n  Доказательство. WBS из 13 узлов и 20 операций в правильных разделах.\\n\\n  Типичная ошибка. Менять Activity ID после выпуска baseline без необходимости: разрушается\\n  сопоставление с отчетами и импортами.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Что обычно является стабильным идентификатором операции?\",\"answer\":\"Activity ID.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":4,\"title\":\"День 4. Операции, вехи, LOE и виды процента выполнения Цель дня. Выбирать Activity Type и Percent Complete Type осознанно.\",\"goal\":\"Выбирать Activity Type и Percent Complete Type осознанно.\",\"full\":\"День 4. Операции, вехи, LOE и виды процента\\nвыполнения\\n  Цель дня. Выбирать Activity Type и Percent Complete Type осознанно.\\n\\nЧто нужно понять\\n  Task Dependent рассчитывается по календарю операции. Resource Dependent - по календарям\\n   назначенных ресурсов. Для учебного строительного графика основной тип - Task Dependent.\\n  Start/Finish Milestone имеют нулевую длительность. Level of Effort тянется между управляющими связями и\\n   не должен задавать критический путь.\\n  Duration % подходит для работ, где прогресс связан с оставшейся длительностью; Physical % - для\\n   измеримого физического результата; Units % - для производительности по трудозатратам.\\n\\nПрактика в P6\\n1. Импортируйте или внесите операции из листа Activities/CSV.\\n2. Проверьте 6 LOE, стартовую и финишную вехи, 0-дневные milestones.\\n3. Для земляных/монтажных работ задайте Physical, для офисных - Duration, для массовых\\n   трудозатратных работ - Units там, где это обосновано.\\n4. Добавьте Steps для операции ERT-0050 и назначьте веса шагов.\\n\\nКонтроль результата\\n  Доказательство. 183 операции, типы и проценты выполнения без случайных значений.\\n\\n  Типичная ошибка. Считать физический прогресс по времени автоматически. 50% длительности не\\n  обязательно означает 50% выполненного объема.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Какая веха имеет нулевую длительность?\",\"answer\":\"Start или Finish Milestone.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":5,\"title\":\"День 5. Логика связей и первый CPM-расчет Цель дня. Построить замкнутую сеть без открытых концов и выполнить Schedule.\",\"goal\":\"Построить замкнутую сеть без открытых концов и выполнить Schedule.\",\"full\":\"День 5. Логика связей и первый CPM-расчет\\n  Цель дня. Построить замкнутую сеть без открытых концов и выполнить Schedule.\\n\\nЧто нужно понять\\n  FS - следующая работа начинается после окончания предыдущей. SS - работы стартуют совместно или с\\n   заданным смещением. FF - совместное окончание. SF применяется редко.\\n  Лаг не объясняет работу. Где возможно, заменяйте лаг отдельной операцией: выдержка бетона, доставка,\\n   проверка, согласование.\\n  Каждая обычная операция должна иметь логического предшественника и последователя; исключения -\\n   контрольные вехи и обоснованные LOE.\\n\\nПрактика в P6\\n1. Загрузите 240 связей или создайте минимум один полный участок вручную: фундамент -> днище ->\\n   стенка -> крыша -> испытание.\\n2. Выполните Tools > Schedule (F9), включите Log to File.\\n3. Проверьте Data Date, открытые концы, логику progress override/retained logic и календарь лагов.\\n4. Сохраните Schedule Log в папку проекта.\\n\\nКонтроль результата\\n  Доказательство. График рассчитан, одна стартовая и одна финишная точка, 0 отрицательных\\n  лагов.\\n\\n  Типичная ошибка. Соединять работы только потому, что они расположены рядом в списке. Связь\\n  должна отражать технологическую или управленческую зависимость.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Если операции А (4 дня) → B (6 дней), сколько длится цепочка FS без лагов? \",\"answer\":10,\"answerType\":\"number\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":6,\"title\":\"День 6. Ограничения, float, longest path и критический путь Цель дня. Отличать расчетную логику от искусственно заданных дат.\",\"goal\":\"Отличать расчетную логику от искусственно заданных дат.\",\"full\":\"День 6. Ограничения, float, longest path и критический\\nпуть\\n  Цель дня. Отличать расчетную логику от искусственно заданных дат.\\n\\nЧто нужно понять\\n  Total Float показывает допустимый сдвиг до выбранной контрольной даты с учетом текущей сети. Free\\n   Float - сдвиг без влияния на ранний старт непосредственного последователя.\\n  Критический путь лучше анализировать как longest path, а не только по цвету «Total Float <= 0».\\n  Hard constraints могут скрыть причинно-следственную связь. В учебном проекте оставлены только\\n   контроль старта и контрактного финиша.\\n\\nПрактика в P6\\n1. Добавьте колонки Total Float, Free Float, Longest Path, Primary Constraint, Constraint Date.\\n2. Запустите F9 с Calculate Multiple Float Paths и отметьте 19 операций longest path.\\n3. Создайте фильтры Critical и Near Critical (например, TF <= 10 рабочих дней).\\n4. Временно задайте Must Finish By на слишком раннюю дату, увидьте negative float, затем удалите\\n   учебное ограничение.\\n\\nКонтроль результата\\n  Доказательство. Layout RVS_02_CRITICAL с критическими и околокритическими операциями.\\n\\n  Типичная ошибка. «Лечить» отрицательный float ограничениями или ручными датами. Сначала\\n  исправляют логику, производительность и последовательность.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Что может скрывать истинную логику критического пути?\",\"answer\":\"Жёсткие ограничения и ручные даты.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":7,\"title\":\"День 7. Layouts, группировка, фильтры, Activity Codes и UDF Цель дня. Получать разные управленческие представления из одной модели.\",\"goal\":\"Получать разные управленческие представления из одной модели.\",\"full\":\"День 7. Layouts, группировка, фильтры, Activity Codes и\\nUDF\\n  Цель дня. Получать разные управленческие представления из одной модели.\\n\\nЧто нужно понять\\n  Layout - это не отдельный график, а набор колонок, группировок, фильтров, шкалы времени и bars.\\n  Activity Codes подходят для устойчивых классификаторов; UDF - для дополнительных полей, которых нет в\\n   стандартной структуре.\\n  Фильтр должен быть воспроизводим: указывайте условия, порядок AND/OR и сохраняйте название\\n   версии.\\n\\nПрактика в P6\\n1. Создайте layouts: WBS, Critical, 2-Week Lookahead, Procurement, Civil, Tank Erection, Management\\n   Summary.\\n2. Создайте UDF: Quantity, Unit, Drawing No., Delay Reason, Recovery Action.\\n3. Сгруппируйте по Discipline и Responsible; добавьте subtotals по Budgeted Cost.\\n4. Экспортируйте layout в файл или сохраните его как Project layout.\\n\\nКонтроль результата\\n  Доказательство. Минимум 7 layouts и 5 UDF, которые реально используются.\\n\\n  Типичная ошибка. Делать копии проектов для каждого вида отчета. Нужны layouts и filters, а не\\n  параллельные несогласованные графики.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Нужно ли копировать проект ради нового Layout?\",\"answer\":\"Нет, Layout — представление одной модели.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":8,\"title\":\"День 8. Ресурсы, роли, ставки и трудозатраты Цель дня. Загрузить 46 ресурсов и понять Units/Time, Budgeted Units и Cost.\",\"goal\":\"Загрузить 46 ресурсов и понять Units/Time, Budgeted Units и Cost.\",\"full\":\"День 8. Ресурсы, роли, ставки и трудозатраты\\n  Цель дня. Загрузить 46 ресурсов и понять Units/Time, Budgeted Units и Cost.\\n\\nЧто нужно понять\\n  Labor, Nonlabor и Material ведут себя по-разному. Для людей и техники единицы часто выражаются\\n   часами; для материалов - физическими единицами.\\n  Budgeted Units = Units/Time x Duration при линейном распределении. Ставка превращает единицы в\\n   ресурсную стоимость.\\n  Role описывает требуемую компетенцию, Resource - конкретный исполнитель или агрегированный экипаж.\\n\\nПрактика в P6\\n1. Создайте ресурсы вручную или через шаблон: руководство, инженеры, бригады, техника, материалы.\\n2. Проверьте Resource ID, Type, Calendar, Max Units/Time и Price/Unit.\\n3. Назначьте ресурсы минимум на 25 операций вручную, затем загрузите остальные назначения.\\n4. Откройте Resource Usage Profile и Resource Usage Spreadsheet.\\n\\nКонтроль результата\\n  Доказательство. 46 ресурсов, 221 назначение, учебная ресурсная стоимость 167 413 200 ₽.\\n\\n  Типичная ошибка. Путать количество людей с трудозатратами. 10 сварщиков по 10 часов - это 100\\n  человеко-часов за смену.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"6 работников по 8 часов ежедневно дают сколько чел.-ч в день?\",\"answer\":48,\"answerType\":\"number\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":9,\"title\":\"День 9. Перегрузка, профили и ресурсное выравнивание Цель дня. Найти конфликт ресурсов и сделать осознанный recovery-план.\",\"goal\":\"Найти конфликт ресурсов и сделать осознанный recovery-план.\",\"full\":\"День 9. Перегрузка, профили и ресурсное выравнивание\\n  Цель дня. Найти конфликт ресурсов и сделать осознанный recovery-план.\\n\\nЧто нужно понять\\n  Гистограмма показывает спрос по времени. Перегрузка не всегда означает ошибку: сначала проверяют\\n   Max Units/Time, календарь и параллельность.\\n  Resource Leveling меняет даты на основании приоритетов и доступности. До запуска сделайте копию или\\n   baseline и задайте правила.\\n  В строительном графике выравнивание не заменяет производственный анализ фронтов, сменности и\\n   техники.\\n\\nПрактика в P6\\n1. Найдите пиковую загрузку сварочной бригады и крана 90 т.\\n2. Создайте сценарий: ограничьте доступность сварщиков, выполните Level Resources и сравните finish.\\n3. Верните исходный график и создайте recovery: вторая смена или параллельный фронт.\\n4. Зафиксируйте разницу в Change Log.\\n\\nКонтроль результата\\n  Доказательство. До/после: ресурсный профиль, дата окончания и объяснение принятого решения.\\n\\n  Типичная ошибка. Нажимать Level Resources с настройками по умолчанию и принимать новую дату\\n  без проверки логики.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Что означает выравнивание ресурсов?\",\"answer\":\"Устранение перегрузок путём перестройки загрузки и/или дат.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":10,\"title\":\"День 10. Expenses, Cost Accounts и базовый план Цель дня. Сформировать полный бюджет и зафиксировать baseline.\",\"goal\":\"Сформировать полный бюджет и зафиксировать baseline.\",\"full\":\"День 10. Expenses, Cost Accounts и базовый план\\n  Цель дня. Сформировать полный бюджет и зафиксировать baseline.\\n\\nЧто нужно понять\\n  Resource Cost связан с назначениями. Expense нужен для закупок, услуг, логистики и иных затрат, которые\\n   нецелесообразно моделировать ресурсом.\\n  Baseline - снимок утвержденного плана. Он нужен для сравнения Start/Finish, Duration, Units и Cost.\\n  После утверждения baseline нельзя тихо переписывать. Изменение проходит через Change Log и\\n   согласование.\\n\\nПрактика в P6\\n1. Загрузите 12 расходов общей стоимостью 109 100 000 ₽.\\n2. Создайте Cost Accounts по разделам: Engineering, Procurement, Civil, Tank, Mechanical, E&I, Coating,\\n   Commissioning, PM.\\n3. Project > Maintain Baselines: создайте BL1 Approved Baseline.\\n4. Project > Assign Baselines: назначьте BL1 как Project Primary Baseline и включите baseline bars.\\n\\nКонтроль результата\\n  Доказательство. Общий бюджет 276 513 200 ₽ и отображение baseline bars/variance columns.\\n\\n  Типичная ошибка. Создать baseline после внесения фактического прогресса или задержек. Сначала\\n  фиксируется утвержденный план.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Для чего фиксируется Baseline?\",\"answer\":\"Для сравнения фактического состояния и текущего прогноза с утверждённым планом.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":11,\"title\":\"День 11. Обновление по факту: Data Date, actuals и remaining duration Цель дня. Правильно внести Update 1 и Update 2 и получить прогноз.\",\"goal\":\"Правильно внести Update 1 и Update 2 и получить прогноз.\",\"full\":\"День 11. Обновление по факту: Data Date, actuals и\\nremaining duration\\n  Цель дня. Правильно внести Update 1 и Update 2 и получить прогноз.\\n\\nЧто нужно понять\\n  Actual Start/Finish - факты. Remaining Duration - оценка оставшегося времени. Physical % - измеренный\\n   объем. Эти поля нельзя подменять друг другом.\\n  Data Date переносится на отчетную дату до запуска F9. Операции в прошлом без actuals и будущие actuals\\n   требуют разбирательства.\\n  Retained Logic сохраняет незавершенную логику; Progress Override может разрешить фактическую работу\\n   вопреки предшественникам. Выбор должен быть осознан.\\n\\nПрактика в P6\\n1. Сделайте копию текущего проекта или сохраните layout и baseline.\\n2. Установите Data Date 05.10.2026, внесите UPDATE_01, выполните F9.\\n3. Сравните BL Start/Finish, Start/Finish Variance, Total Float и критический путь.\\n4. Повторите для Data Date 02.11.2026 и оформите недельный комментарий.\\n\\nКонтроль результата\\n  Доказательство. Два обновления с сохраненными Schedule Log и отчетом причин отклонения.\\n\\n  Типичная ошибка. Проставлять Percent Complete без Actual Start или оставлять завершенную\\n  операцию без Actual Finish.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Data Date отделяет что?\",\"answer\":\"Фактическое прошлое от расчётного будущего.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":12,\"title\":\"День 12. Обновления 3-6, прогноз и recovery Цель дня. Проследить, как задержка поставки и сварки меняет критический путь.\",\"goal\":\"Проследить, как задержка поставки и сварки меняет критический путь.\",\"full\":\"День 12. Обновления 3-6, прогноз и recovery\\n  Цель дня. Проследить, как задержка поставки и сварки меняет критический путь.\\n\\nЧто нужно понять\\n  Прогноз должен отражать реальную производительность, а не желаемую дату. Remaining Duration\\n   пересматривается по факту выработки.\\n  Recovery-план документирует конкретные меры: дополнительная смена, изменение последовательности,\\n   ускоренная поставка, разделение фронта.\\n  После каждой меры проверяйте безопасность, технологию, ресурсную загрузку и изменение бюджета.\\n\\nПрактика в P6\\n1. Последовательно внесите Update 3-6 из папки 04_ОБНОВЛЕНИЯ_ПО_ФАКТУ.\\n2. На Update 4 найдите влияние ремонта сварных швов; на Update 5 смоделируйте вторую смену.\\n3. Сравните Forecast Finish до и после recovery, а также ресурсный пик и стоимость.\\n4. Внесите решение в Delay Register и Change Log.\\n\\nКонтроль результата\\n  Доказательство. Таблица шести Data Date: Forecast Finish, variance, критический участок, действие\\n  и владелец.\\n\\n  Типичная ошибка. Восстанавливать срок простым уменьшением Remaining Duration без\\n  производственного обоснования.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"После изменения длительности работы необходимо что?\",\"answer\":\"Пересчитать график и проверить влияние на критический путь.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":13,\"title\":\"День 13. Earned Value, S-curve, look-ahead и недельный отчет Цель дня. Перевести данные графика в управленческий отчет.\",\"goal\":\"Перевести данные графика в управленческий отчет.\",\"full\":\"День 13. Earned Value, S-curve, look-ahead и недельный\\nотчет\\n  Цель дня. Перевести данные графика в управленческий отчет.\\n\\nЧто нужно понять\\n  PV - стоимость запланированной работы к Data Date. EV - бюджетная стоимость фактически выполненного\\n   объема. AC - фактическая стоимость.\\n  SPI = EV / PV; CPI = EV / AC. Значения меньше 1 показывают отставание по сроку или перерасход\\n   относительно выполненного объема.\\n  S-curve должна использовать time-distributed данные, а не равномерно размазанный итоговый бюджет без\\n   оснований.\\n\\nПрактика в P6\\n1. Назначьте baseline для EV и проверьте настройки Earned Value Calculation.\\n2. Заполните S_Curve в книге Шаблоны_планировщика_P6.xlsx.\\n3. Сформируйте 2-недельный look-ahead от Data Date.\\n4. Заполните Weekly Report: план/факт, SPI/CPI, критический путь, top risks, решения.\\n\\nКонтроль результата\\n  Доказательство. S-curve, look-ahead и недельный отчет на одну выбранную Data Date.\\n\\n  Типичная ошибка. Использовать SPI/CPI без проверки качества baseline, фактических затрат и\\n  правила начисления прогресса.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"SPI=0,8 означает опережение графика?\",\"answer\":\"Нет, по этому показателю освоенная стоимость ниже плановой.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":14,\"title\":\"День 14. QA графика, итоговый экзамен и выпуск пакета планировщика Цель дня. Самостоятельно проверить график и защитить принятые решения.\",\"goal\":\"Самостоятельно проверить график и защитить принятые решения.\",\"full\":\"День 14. QA графика, итоговый экзамен и выпуск пакета\\nпланировщика\\n  Цель дня. Самостоятельно проверить график и защитить принятые решения.\\n\\nЧто нужно понять\\n  Хороший график - это не красивая диаграмма Ганта, а проверяемая сеть с понятными календарями,\\n   ресурсами, baseline, actuals и прогнозом.\\n  Перед выпуском фиксируют Data Date, Schedule Options, Schedule Log, change history и версию файла.\\n  Любое отклонение должно иметь причину, влияние, действие, владельца и срок решения.\\n\\nПрактика в P6\\n1. Выполните чек-лист Schedule_QA из мастер-файла.\\n2. Сдайте практический экзамен из отдельного документа.\\n3. Соберите выпуск: график, Schedule Log, 2W look-ahead, weekly report, S-curve, risk/delay/change\\n   registers.\\n4. Защитите критический путь и recovery-план устно за 10 минут.\\n\\nКонтроль результата\\n  Доказательство. Полный комплект отчетности и результат экзамена не ниже 80%.\\n\\n  Типичная ошибка. Заканчивать работу после F9. Расчет - только начало анализа, проверки и\\n  объяснения прогноза.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\\n\\n    4. ПРОФЕССИОНАЛЬНАЯ ПРАКТИКА\\n                  Как читать и защищать график, а не только вводить данные\\n\\n4.1. Правила качественной логики\\n  Связь должна описывать реальное технологическое, контрактное или информационное условие.\\n  Используйте FS по умолчанию только тогда, когда работа действительно не может стартовать раньше\\n   полного окончания предшественника.\\n  SS/FF применяйте для параллельных процессов, но проверяйте, что сеть не создает невозможный\\n   прогноз.\\n  Заменяйте длительный lag отдельной операцией с названием, ответственным и календарем.\\n  Не оставляйте обычные операции без предшественников/последователей.\\n  Не используйте constraints для сокрытия отсутствующей логики.\\n\\nМини-задача: объяснить участок монтажа\\n                   ID                                     Операция                                     Предшественники\\n\\nCIV-0190                                 Приемка фундамента под монтаж резервуара        CIV-0180 FS\\n\\n                                         Разложить и рассортировать листы на\\nERT-0020                                                                                 FAB-0110 FS, ERT-0010 FS\\n                                         площадке\\n\\nERT-0030                                 Разметить и уложить листы днища                 ERT-0020 FS\\n\\nERT-0040                                 Сборка и сварка окраек днища                    ERT-0030 FS\\n\\nERT-0050                                 Сборка и сварка центральной части днища         ERT-0040 FS\\n\\nERT-0060                                 Вакуумный контроль швов днища                   PRC-0130 FS, ERT-0050 FS\\n\\nERT-0070                                 Сборка первого пояса стенки                     ERT-0060 FS\\n\\nERT-0080                                 Сварка первого пояса стенки                     ERT-0070 FS\\n\\nERT-0090                                 НК первого пояса стенки                         ERT-0080 FS\\n\\nERT-0100                                 Сборка второго пояса стенки                     ERT-0090 FS\\n\\nERT-0110                                 Сварка второго пояса стенки                     ERT-0100 FS\\n\\nERT-0120                                 НК второго пояса стенки                         ERT-0110 FS\\n\\n4.2. Schedule Options и Schedule Log\\nСохраняйте настройки расчета вместе с версией графика. Одинаковая сеть при разных options может\\nдать разные даты.\\n  ☐ Data Date соответствует отчетному периоду.\\n  ☐ Log to File включен и файл сохранен с датой.\\n  ☐ Проверено правило фактической работы: Retained Logic / Progress Override / Actual Dates.\\n  ☐ Выбран календарь расчета lag.\\n  ☐ Включен расчет нескольких float paths, если нужен анализ near critical.\\n  ☐ Проверены out-of-sequence progress, open ends, constraints, negative float, relationship lags.\\n  ☐ Forecast Finish сопоставлен с контрактным финишем.\\n\\n4.3. Базовый план и управление изменениями\\n                          Событие                                                             Действие\\n\\n                                                                   Создать Approved Baseline, назначить Primary Baseline,\\nПлан согласован\\n                                                                   зафиксировать Schedule Log и PDF/XLSX-выгрузку.\\n\\n                             Событие                                                    Действие\\n\\n                                                             Создать Change Request, добавить/удалить операции и сохранить\\nИзменен объем\\n                                                             влияние на срок/стоимость.\\n\\n                                                             Создать новую baseline-версию или обновить baseline в\\nУтверждено изменение\\n                                                             соответствии с процедурой проекта.\\n\\n                                                             Сохранить baseline, изменить current schedule, показать разницу и\\nRecovery без изменения контракта\\n                                                             ресурсно-стоимостные последствия.\\n\\nНеутвержденная идея                                          Моделировать в копии/what-if, не в официальной версии.\\n\\n4.4. Ресурсный анализ\\n              Тип ресурса                             Количество                              Бюджет назначений\\n\\nLabor                                  31                                          66 627 400 ₽\\n\\nMaterial                               5                                           80 974 000 ₽\\n\\nNonlabor                               10                                          19 811 800 ₽\\n\\n  Сначала проверяйте календарь и Max Units/Time, затем факт перегрузки.\\n  Различайте трудозатраты и численность/единицы техники.\\n  Проверяйте профиль по критическим ресурсам: сварщики, монтажники, кран, NDT, АКЗ.\\n  Любое ускорение должно быть связано с конкретным ресурсным решением.\\n\\n4.5. Earned Value и формулы\\n                Показатель                             Формула                                       Смысл\\n\\n                                                                                   Сколько работы по baseline должно быть\\nPV                                     Плановая стоимость к Data Date\\n                                                                                   выполнено.\\n\\n                                       Бюджетная стоимость выполненного            Сколько бюджетной стоимости заработано\\nEV\\n                                       объема                                      фактом.\\n\\nAC                                     Фактическая стоимость                       Сколько реально потрачено.\\n\\n                                                                                   Отклонение по сроку в стоимостном\\nSV                                     EV - PV\\n                                                                                   выражении.\\n\\nCV                                     EV - AC                                     Отклонение стоимости.\\n\\nSPI                                    EV / PV                                     < 1 - отставание; > 1 - опережение.\\n\\nCPI                                    EV / AC                                     < 1 - перерасход; > 1 - экономия.\\n\\n                                                                                   Прогноз итоговой стоимости при\\nEAC                                    BAC / CPI (один из вариантов)\\n                                                                                   сохранении тенденции.\\n\\n  Осторожно. EV не исправляет плохой baseline, неверные actual costs или формальный Physical %.\\n  Перед интерпретацией индексов проверьте качество исходных данных.\\n\\n                  5. ОБНОВЛЕНИЯ ПО ФАКТУ\\n                          Шесть Data Date, причины отклонений и recovery\\n\\n             Data Date                     Состояние                    Главное отклонение                   Задача анализа\\n\\n                                 Инженерные работы и              Техническая оценка металла +3     Проверить стартовые actuals,\\n05.10.2026\\n                                 мобилизация                      рабочих дня                       baseline variance и Schedule Log.\\n\\n                                                                  Заказ металла и vendor data +5    Пересмотреть Remaining Duration\\n02.11.2026                       Фундамент в работе\\n                                                                  дней                              и прогноз поставки.\\n\\n                                 Фундамент принят, металл                                           Определить влияние на монтаж\\n07.12.2026                                                        Партия 1 прогнозируется +7 дней\\n                                 изготавливается                                                    днища и near-critical path.\\n\\n                                 Партия 1 на площадке, начато     Ремонт сварных швов и поздний     Разделить ремонт, повторный\\n01.02.2027\\n                                 днище                            старт монтажа                     NDT и остаток работ.\\n\\n                                                                                                    Сравнить срок, ресурсный пик и\\n05.04.2027                       Монтаж стенки                    Введена вторая сварочная смена\\n                                                                                                    стоимость recovery.\\n\\n                                                                  Гидроиспытание и внутренняя       Сформировать финальный\\n07.06.2027                       Механическая готовность\\n                                                                  АКЗ определяют финиш              прогноз и план приемки.\\n\\n5.1. Стандартный цикл обновления\\n1. Собрать подтвержденные actuals и остаточные оценки от ответственных.\\n2. Сохранить текущую версию и установить новую Data Date.\\n3. Внести Actual Start/Finish, Remaining Duration, Physical/Units %, Actual Units/Cost.\\n4. Проверить out-of-sequence progress и фактические даты за Data Date.\\n5. Выполнить F9 и сохранить Schedule Log.\\n6. Сравнить baseline и current: milestones, forecast finish, float, critical/near-critical paths.\\n7. Обновить Delay Register, Change Log, Risk Register, 2W look-ahead и weekly report.\\n8. Зафиксировать решения, владельцев и сроки действий.\\n\\n5.2. Как формулировать отклонение\\n                               Поле                                                             Пример\\n\\n                                                                  Поставка партии листовой стали сдвинута на 7 календарных\\nПричина\\n                                                                  дней.\\n\\n                                                                  Старт раскладки днища сдвигается на 5 рабочих дней; float\\nВоздействие\\n                                                                  участка снижается до 2 дней.\\n\\n                                                                  Разделить поставку по партиям, мобилизовать вторую смену\\nДействие\\n                                                                  сварщиков, заранее подготовить laydown.\\n\\nВладелец                                                          Менеджер закупок / начальник участка.\\n\\nСрок решения                                                      До следующей Data Date или конкретная календарная дата.\\n\\n                                                                  Письмо поставщика, обновленный график, ресурсный\\nДоказательство\\n                                                                  профиль, change record.\\n\\n5.3. Recovery-план: что проверять\\n  ☐ Мера связана с конкретной операцией и причиной.\\n  ☐ Новая длительность подтверждена производительностью и ресурсами.\\n  ☐ Календари/смены реалистичны и согласованы.\\n  ☐ Не нарушены HSE, качество, технологическая последовательность и hold points.\\n  ☐ Проверена перегрузка людей и техники.\\n\\n  ☐ Показана дополнительная стоимость.\\n  ☐ Forecast Finish действительно улучшился после F9.\\n  ☐ Изменение отражено в Change Log и weekly report.\\n\\n                       6. КОНТРОЛЬ КАЧЕСТВА\\n                               Проверки перед выпуском каждого графика\\n\\n6.1. Базовый QA-чек-лист\\n                            Проверка                                              Критерий\\n\\nУникальность ID                                     Нет дубликатов Activity ID.\\n\\nОткрытые концы                                      Только обоснованные стартовая/финишная вехи и LOE.\\n\\n                                                    Нет отрицательных lag; положительные минимальны и\\nЛаги\\n                                                    объяснены.\\n\\nConstraints                                         Только необходимые контрольные ограничения.\\n\\nДлительности                                        Длинные операции декомпозированы либо обоснованы.\\n\\nКалендари                                           Каждая операция использует правильный режим работы.\\n\\nФактические даты                                    Нет будущих actuals и незавершенных операций с Actual Finish.\\n\\nData Date                                           Соответствует отчетному периоду.\\n\\nCritical path                                       Путь логичен и заканчивается на контрактной/финишной вехе.\\n\\nNear critical                                       Проверены несколько float paths и ключевые риски.\\n\\nРесурсы                                             Нет необъясненной перегрузки критических ресурсов.\\n\\nBaseline                                            Назначена верная версия и показаны variance columns.\\n\\nСтоимость                                           Resource Costs + Expenses сходятся с контрольным бюджетом.\\n\\n                                                    Schedule Log, look-ahead, S-curve и реестры имеют одну Data\\nОтчетность\\n                                                    Date.\\n\\n6.2. Контрольные цифры комплекта\\n                           Показатель                                             Ожидаемо\\n\\nОпераций                                            183\\n\\nСвязей                                              240\\n\\nРесурсов                                            46\\n\\nНазначений                                          221\\n\\nExpenses                                            12\\n\\nКритических longest path                            19\\n\\nNear critical                                       78\\n\\nОткрытые начала/окончания                           1/1\\n\\nОтрицательные лаги                                  0\\n\\nОграничения                                         2\\n\\nЦиклы                                               0\\n\\nОбщий бюджет                                        276 513 200 ₽\\n\\nБазовый finish                                      2027-12-07 08:00\\n\\nКонтрактный finish                                  2027-12-20 18:00\\n\\n  Допуск различий. После импорта в P6 даты могут немного отличаться из-за календарных\\n  исключений, настроек lag, start/finish rules, time units и способа обработки XML. Объясните различие,\\n  а не подгоняйте числа вручную.\\n\\n6.3. Критерии готовности планировщика\\n                          Уровень                                                 Критерий\\n\\n                                                       Создает проект, WBS, календари, операции и связи; запускает\\nБазовый\\n                                                       F9.\\n\\n                                                       Объясняет critical/float, ведет baseline и actuals, выпускает\\nРабочий\\n                                                       look-ahead.\\n\\n                                                       Анализирует ресурсы, несколько float paths, EV, причины и\\nУверенный\\n                                                       recovery.\\n\\n                                                       За 10 минут защищает структуру графика, критический путь,\\nГотов к собеседованию\\n                                                       обновление и управленческий вывод.\\n\\n                               7. СПРАВОЧНИК\\n                   Термины, последовательности и официальные источники\\n\\n7.1. Мини-глоссарий\\n                           Термин                                                   Определение\\n\\nEPS                                                       Enterprise Project Structure - иерархия проектов/портфеля.\\n\\nOBS                                                       Organizational Breakdown Structure - ответственность и права.\\n\\nWBS                                                       Work Breakdown Structure - декомпозиция результата проекта.\\n\\n                                                          Операция с логикой, длительностью, календарем и\\nActivity\\n                                                          ответственностью.\\n\\nMilestone                                                 Нулевая длительность, контрольное событие.\\n\\n                                                          Level of Effort - поддерживающая работа, растянутая между\\nLOE\\n                                                          связями.\\n\\nData Date                                                 Граница между фактом и прогнозом.\\n\\nBaseline                                                  Зафиксированный утвержденный план для сравнения.\\n\\nOriginal Duration                                         Первоначальная длительность операции.\\n\\nRemaining Duration                                        Оценка времени до завершения незаконченной операции.\\n\\nActual Start/Finish                                       Подтвержденные фактические даты.\\n\\nEarly Start/Finish                                        Самые ранние даты по логике и календарям.\\n\\nLate Start/Finish                                         Самые поздние даты без сдвига выбранного окончания.\\n\\nTotal Float                                               Резерв относительно конечного ограничения/финиша сети.\\n\\n                                                          Резерв без влияния на ранний старт непосредственного\\nFree Float\\n                                                          последователя.\\n\\nLongest Path                                              Цепочка, определяющая расчетное окончание проекта.\\n\\n                                                          Фактическая работа выполнена вопреки логике\\nOut-of-sequence progress\\n                                                          предшественников.\\n\\nResource Leveling                                         Пересчет дат с учетом ограниченной доступности ресурсов.\\n\\nPV / EV / AC                                              Плановая стоимость / освоенный объем / фактическая стоимость.\\n\\nSPI / CPI                                                 Индексы выполнения по сроку / стоимости.\\n\\n7.2. Последовательность действий перед F9\\n1. Проверить открытую версию проекта и Data Date.\\n2. Проверить фактические даты, статусы и Remaining Duration.\\n3. Проверить новые/измененные связи, constraints и calendars.\\n4. Проверить Schedule Options.\\n5. Выполнить F9 с Log to File.\\n6. Открыть log и устранить ошибки/предупреждения.\\n7. Проверить finish, critical/near critical, negative float и ресурсные пики.\\n8. Сохранить версию и выпускные отчеты.\\n\\n7.3. Официальные источники Oracle\\n                                Источник                                                                 Адрес\\n\\n                                                                       https://docs.oracle.com/cd/G48902_01/English/User_Guides/p6_pro_user/\\nP6 Professional User Guide, Version 26\\n                                                                       toc.htm\\n\\nP6 Professional Help, Version 26                                       https://docs.oracle.com/cd/G48902_01/client_help/en_US/toc.htm\\n\\n                                                                       https://docs.oracle.com/cd/G48902_01/English/admin/p6_pro_admin/\\nP6 Professional Administration Guide - import privileges\\n                                                                       48405.htm\\n\\n                                                                       https://docs.oracle.com/en/industries/construction-engineering/primavera-\\nPrimavera P6 Professional documentation landing page\\n                                                                       p6-professional/\\n\\n  Версионность. Пункты меню и доступные поля импорта могут отличаться в разных выпусках и\\n  локализациях. При расхождении ориентируйтесь на Help вашей установленной версии и служебные\\n  заголовки экспортированного XLSX.\\n\\n7.4. Следующий шаг после курса\\nПеренесите навык на второй проект без готового набора: составьте WBS, словарь операций, календари,\\nлогическую схему, ресурсный справочник и правила обновления. Умение повторить процесс на новом\\nобъекте - главный критерий, что Primavera освоена, а не просто заполнен учебный файл.\\n  ☐ Сдать экзамен не ниже 80%.\\n  ☐ Повторить проект с нуля без подсказки.\\n  ☐ Сделать 30-дневное закрепление по трекеру.\\n  ☐ Подготовить 10-минутный рассказ о графике для собеседования.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Что включают в QA графика?\",\"answer\":\"Открытые концы, связи, ограничения, длительности, календари и ресурсы.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"}]};\nconst PRODUCT_MODE='p6';let DATA=COURSE_DATA;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>\"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[x]));\nlet state={section:'home',course:'cad',day:1};let completed=(()=>{try{return JSON.parse(localStorage.getItem('izn_progress_v1')||'{}')}catch{return {}}})();\nfunction save(){try{localStorage.setItem('izn_progress_v1',JSON.stringify(completed))}catch{}}const days=id=>DATA[id]||[];\nfunction render(){const links=[['home','Обзор'],['cad','AutoCAD'],['p6','Primavera'],['drawing','Чертёж'],['schedule','График']].filter(([id])=>PRODUCT_MODE==='all'||(PRODUCT_MODE==='cad'?['home','cad','drawing'].includes(id):['home','p6','schedule'].includes(id)));$('#tabs').innerHTML=links.map(([id,label])=>`<button data-go=\"${id}\" class=\"${state.section===id?'active':''}\">${label}</button>`).join('');\nif(state.section==='home')home();else if(['cad','p6'].includes(state.section))course(state.section);else if(state.section==='lesson')lesson();else if(state.section==='drawing')drawing();else if(state.section==='schedule')schedule();}\nfunction home(){let c=Object.keys(completed).filter(k=>completed[k]&&(PRODUCT_MODE==='all'||k.startsWith(PRODUCT_MODE))).length;const TOTAL=Object.values(DATA).reduce((a,x)=>a+x.length,0);$('#view').innerHTML=`<section class=\"card\"><h2>Учись, выполняй и проверяй</h2><p>Полноценный мобильный учебник с самостоятельными заданиями. Данные сохраняются на устройстве. Все числовые примеры — условный учебный проект РВС-5000.</p><div class=\"grid\"><button class=\"tile\" data-go=\"cad\"><b>21 день</b>AutoCAD<br><small>DWG, размеры, проект/факт</small></button><button class=\"tile\" data-go=\"p6\"><b>14 дней</b>Primavera P6<br><small>WBS, CPM, baseline, план-факт</small></button></div><p class=\"muted\">Пройдено уроков: <b>${c} / ${TOTAL}</b></p><div class=\"bar\"><div style=\"width:${Math.round(c/Math.max(TOTAL,1)*100)}%\"></div></div></section><section class=\"card\"><h2>Работа прямо на телефоне</h2><div class=\"row\"><button class=\"btn outline\" data-go=\"drawing\">Открыть CAD-практику</button><button class=\"btn outline\" data-go=\"schedule\">Открыть CPM-график</button></div><p class=\"notice\">Тренажёры выполняют учебные вычисления и не являются программами Autodesk или Oracle. AutoCAD Mobile / Primavera требуют собственных прав доступа и лицензий.</p></section>`;if(PRODUCT_MODE==='cad')document.querySelectorAll('[data-go=\"p6\"],[data-go=\"schedule\"]').forEach(x=>x.remove());if(PRODUCT_MODE==='p6')document.querySelectorAll('[data-go=\"cad\"],[data-go=\"drawing\"]').forEach(x=>x.remove())}\nfunction course(id){if(PRODUCT_MODE!=='all'&&id!==PRODUCT_MODE)return home();state.course=id;let a=days(id),c=a.filter(x=>completed[id+x.day]).length;$('#view').innerHTML=`<section class=\"card\"><h2>${id==='cad'?'AutoCAD · 21 день':'Primavera P6 · 14 дней'}</h2><p class=\"muted\">${id==='cad'?'Мобильная адаптация курса по исполнительной документации':'Полный текст 14-дневного курса P6 Professional с мобильными тренировками'}</p><div class=\"bar\"><div style=\"width:${Math.round(c/a.length*100)}%\"></div></div><p>${c} из ${a.length} дней завершено</p></section><section class=\"days\">${a.map(x=>`<button class=\"day ${completed[id+x.day]?'done':''}\" data-lesson=\"${id}:${x.day}\"><strong>${completed[id+x.day]?'✓ ':''}День ${x.day}</strong><small>${esc(x.title)}</small></button>`).join('')}</section>`;}\nfunction lesson(){let a=days(state.course),x=a.find(l=>l.day===state.day);if(!x){state.section=state.course;return render()};let value=completed[state.course+x.day];$('#view').innerHTML=`<div class=\"row\" style=\"margin-bottom:12px\"><button class=\"btn soft\" data-go=\"${state.course}\">← К дням</button><span class=\"pill\">День ${x.day}/${a.length}</span></div><section class=\"card\"><h2>${esc(x.title)}</h2><p>${esc(x.goal)}</p>${state.course==='p6'?`<p class=\"notice\">${esc(x.phoneTip)}</p><details><summary>Полный материал урока · читать</summary><pre>${esc(x.full)}</pre></details>`:`<h3>Что важно понять</h3><p>${esc(x.concept)}</p><h3>Практика на телефоне</h3><p>${esc(x.explanation)}</p><p>${esc(x.mobileSteps)}</p><h3>Контрольный результат</h3><p>${esc(x.deliverable)}</p><div class=\"notice\">Частая ошибка: ${esc(x.pitfall)}. Возможности Autodesk AutoCAD Mobile могут отличаться от Windows.</div>`}<div class=\"row\"><button class=\"btn outline\" data-go=\"${state.course==='cad'?'drawing':'schedule'}\">Открыть учебный инструмент</button><button class=\"btn soft\" data-action=\"speak\">Прослушать</button></div></section><section class=\"card\"><h2>Проверка урока</h2><p>${esc(x.challenge)}</p><input id=\"checkanswer\" class=\"field\" placeholder=\"${x.answerType==='number'?'Введите результат числом':'Запишите краткий ответ'}\" inputmode=\"${x.answerType==='number'?'decimal':'text'}\"><div class=\"row\"><button class=\"btn\" data-action=\"check\">Проверить</button><button class=\"btn soft\" data-action=\"showAnswer\">Показать разбор</button></div><div id=\"feedback\" style=\"margin:12px 0\"></div><button class=\"btn outline full\" data-action=\"done\">${value?'✓ Урок пройден · подтвердить':'Отметить выполнение практики'}</button><p class=\"muted\">Отметка урока означает самостоятельное выполнение. Знание программы не подтверждается официальным сертификатом.</p></section>`;}\nfunction check(){let x=days(state.course).find(l=>l.day===state.day),u=$('#checkanswer').value.trim();let answer=x.answer;let okay=x.answerType==='number'?u!==''&&Math.abs(Number(u.replace(',','.'))-Number(answer))<.03:u.length>5;$('#feedback').innerHTML=`<div class=\"${okay?'success':'error'}\">${okay?'Ответ принят для учебного упражнения.':'Нужно ещё проверить решение или прочитать разбор.'}</div>${x.answerType==='text'?'Для текстового вопроса здесь проверяется только заполнение ответа. Содержание сравните с эталоном; автоматическая смысловая проверка не выполняется.':''}`;}\nfunction showAnswer(){let x=days(state.course).find(l=>l.day===state.day);$('#feedback').innerHTML=`<div class=\"notice\">Учебный эталон: <b>${esc(x.answer)}</b></div>`}\nfunction done(){completed[state.course+state.day]=true;save();let d=state.day;state.day=Math.min(days(state.course).length,d+1);render()}\nfunction speak(){let x=days(state.course).find(l=>l.day===state.day);if(!('speechSynthesis'in window))return alert('На этом устройстве синтез речи не поддерживается');speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance([x.title,x.goal,x.explanation||x.full?.slice(0,1200)||''].join('. '));utterance.lang='ru-RU';speechSynthesis.speak(utterance)}\n// Coordinate-based educational drawing (not DWG editor)\nlet cad={scale:1,ox:0,oy:0,tool:'pan',layers:{project:true,fact:true,point:true},points:[],drag:null};\nfunction drawing(){let key='cad';$('#view').innerHTML=`<section class=\"card\"><h2>CAD-полигон · РВС-5000</h2><p class=\"muted\">Проект: (60000;45000) мм · факт: (60018;44988) мм. Схема намеренно увеличивает отклонение, чтобы его было видно.</p><div class=\"row tools\"><button data-cad=\"pan\">Перемещение</button><button data-cad=\"point\">Точка</button><button data-cad=\"measure\">Измерение</button><button data-cad=\"zoom+\">＋</button><button data-cad=\"zoom-\">－</button><button data-cad=\"reset\">Сброс</button></div><p><label><input id=\"cadproject\" type=\"checkbox\" checked> Проект</label> · <label><input id=\"cadfact\" type=\"checkbox\" checked> Факт</label></p><canvas id=\"cad\" width=\"800\" height=\"500\" aria-label=\"Схема площадки РВС-5000\"></canvas><p id=\"cadout\" class=\"notice\">Касание с выбранным инструментом.</p><div class=\"row\"><button class=\"btn outline\" data-action=\"cadexport\">Экспорт точек DXF</button><button class=\"btn soft\" data-action=\"cadreport\">Скачать отчёт</button></div></section>`;paintCad();}\nfunction cv(){return $('#cad')?.getContext('2d')}const tx=(x,w)=>w/2+(x-60000)/350*cad.scale+cad.ox,ty=(y,h)=>h/2-(y-45000)/350*cad.scale+cad.oy;\nfunction paintCad(){const ctx=cv();if(!ctx)return;const w=800,h=500;ctx.clearRect(0,0,w,h);ctx.fillStyle='#fbfdff';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#e6edf4';for(let i=0;i<w;i+=40){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,h);ctx.stroke()}for(let j=0;j<h;j+=40){ctx.beginPath();ctx.moveTo(0,j);ctx.lineTo(w,j);ctx.stroke()}function ring(x,y,r,col){ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(tx(x,w),ty(y,h),r/350*cad.scale,r/350*cad.scale,0,0,2*Math.PI);ctx.stroke()}\nif(cad.layers.project){ring(60000,45000,12000,'#346ce8');ring(60000,45000,11000,'#4e7ef2');ctx.fillStyle='#346ce8';ctx.fillText('Проект: 60000, 45000',20,26)}if(cad.layers.fact){ring(60018+700,44988-450,12007,'#e38432');ctx.fillStyle='#9f5700';ctx.fillText('Факт: +18 / -12 мм (графически увеличено)',20,47)}ctx.fillStyle='#1e855e';for(let p of cad.points){ctx.beginPath();ctx.arc(tx(p.x,w),ty(p.y,h),4,0,7);ctx.fill()}ctx.font='17px system-ui';ctx.fillStyle='#435875';ctx.fillText('Учебный чертёж · не геодезическая основа',20,h-18)}\nfunction cadInteraction(evt){if(!$('#cad'))return;const rect=$('#cad').getBoundingClientRect();let px=(evt.clientX-rect.left)*800/rect.width,py=(evt.clientY-rect.top)*500/rect.height;let x=60000+((px-400-cad.ox)*350/cad.scale),y=45000-((py-250-cad.oy)*350/cad.scale);if(cad.tool==='point'){cad.points.push({x:Math.round(x),y:Math.round(y)});$('#cadout').textContent='Добавлена точка ('+Math.round(x)+'; '+Math.round(y)+') мм'}else if(cad.tool==='measure'){let p=cad.measure;if(!p){cad.measure={x,y};$('#cadout').textContent='Выберите вторую точку'}else{let dist=Math.hypot(x-p.x,y-p.y);$('#cadout').textContent='Учебная длина: '+dist.toFixed(1)+' мм';cad.measure=null}}paintCad()}\nfunction fileDownload(name,content,mime){const blob=new Blob([content],{type:mime||'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}\nfunction cadExport(){let lines=['0','SECTION','2','ENTITIES'];for(const p of cad.points){lines.push('0','POINT','8','IZN_USER_POINTS','10',String(p.x),'20',String(p.y),'30','0')}lines.push('0','ENDSEC','0','EOF');fileDownload('IZN_учебные_точки.dxf',lines.join('\\n'),'application/dxf')}\n// Editable, mathematically validated basic CPM in working-day units, NOT a full P6 scheduler.\nlet jobs=[{id:'ENG',name:'Проектирование',d:4,p:''},{id:'PRC',name:'Поставка',d:7,p:'ENG'},{id:'CIV',name:'Основание',d:6,p:'ENG'},{id:'MEC',name:'Монтаж',d:5,p:'PRC,CIV'},{id:'TST',name:'Испытания',d:3,p:'MEC'}];let baseline=null;\nfunction cpm(input=jobs){const dict=Object.fromEntries(input.map(x=>[x.id,{...x,prev:x.p.split(',').map(t=>t.trim()).filter(Boolean),ES:0,EF:0,LS:0,LF:0,TF:0}]));if(Object.keys(dict).length!==input.length)throw Error('Повтор Activity ID.');for(const x of Object.values(dict))for(const p of x.prev)if(!dict[p])throw Error('Неизвестная предшествующая операция: '+p);let order=[],seen=new Set();while(order.length<input.length){let ready=Object.values(dict).filter(x=>!seen.has(x.id)&&x.prev.every(p=>seen.has(p)));if(!ready.length)throw Error('Цикл в связях — исправьте предшественников');for(const x of ready){x.ES=x.prev.length?Math.max(...x.prev.map(p=>dict[p].EF)):0;x.EF=x.ES+x.d;if(!(x.d>=0&&Number.isFinite(x.d)))throw Error('Длительность должна быть неотрицательной');order.push(x);seen.add(x.id)}}let duration=Math.max(...order.map(x=>x.EF));for(let i=order.length-1;i>=0;i--){let x=order[i],succ=order.filter(s=>s.prev.includes(x.id));x.LF=succ.length?Math.min(...succ.map(s=>s.LS)):duration;x.LS=x.LF-x.d;x.TF=x.LS-x.ES}return {order,duration}}\nfunction schedule(){let out;try{out=cpm()}catch(e){out={error:e.message}}$('#view').innerHTML=`<section class=\"card\"><h2>CPM-лаборатория · критический путь</h2><p class=\"muted\">Редактируйте длительности и предшественников FS, пересчитывайте ранние и поздние сроки и резервы. Это учебная модель с единым условным календарём, не Oracle P6.</p><div class=\"scroll\"><table><thead><tr><th>ID</th><th>Работа</th><th>Дней</th><th>Предш.</th><th>ES</th><th>EF</th><th>TF</th></tr></thead><tbody>${jobs.map((j,i)=>`<tr><td>${esc(j.id)}</td><td>${esc(j.name)}</td><td><input data-job=\"${i}\" data-key=\"d\" type=\"number\" min=\"0\" step=\"1\" value=\"${j.d}\" style=\"width:60px\"></td><td><input data-job=\"${i}\" data-key=\"p\" value=\"${esc(j.p)}\" style=\"width:90px\"></td><td>${out.error?'—':out.order.find(x=>x.id===j.id).ES}</td><td>${out.error?'—':out.order.find(x=>x.id===j.id).EF}</td><td>${out.error?'—':out.order.find(x=>x.id===j.id).TF}</td></tr>`).join('')}</tbody></table></div><p class=\"${out.error?'error':'success'}\">${out.error?esc(out.error):'Длительность проекта: '+out.duration+' раб. дней · Критические работы: '+out.order.filter(x=>x.TF===0).map(x=>x.id).join(' → ')}</p><div class=\"row\"><button class=\"btn\" data-action=\"calc\">Пересчитать</button><button class=\"btn outline\" data-action=\"baseline\">Зафиксировать baseline</button><button class=\"btn soft\" data-action=\"report\">Отчёт</button></div>${baseline!==null?`<p class=\"notice\">Baseline: ${baseline} дней. Отклонение нового прогноза: ${out.error?'—':out.duration-baseline} дней.</p>`:''}</section>`}\nfunction updateJobs(){document.querySelectorAll('[data-job]').forEach(n=>{let j=jobs[Number(n.dataset.job)];j[n.dataset.key]=n.dataset.key==='d'?Number(n.value):n.value.toUpperCase().trim()})}\nfunction report(){let r;try{r=cpm()}catch(e){return alert(e.message)}fileDownload('RVS5000_CPM_отчёт.csv',['ID;Работа;Дней;Предшественники;ES;EF;LS;LF;TF',...r.order.map(x=>[x.id,x.name,x.d,x.prev.join(','),x.ES,x.EF,x.LS,x.LF,x.TF].join(';'))].join('\\n'),'text/csv;charset=utf-8')}\ndocument.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let go=b.dataset.go,les=b.dataset.lesson,action=b.dataset.action,mode=b.dataset.cad;if(go){state.section=go;render();scrollTo(0,0)}if(les){let[id,day]=les.split(':');state={section:'lesson',course:id,day:Number(day)};render();scrollTo(0,0)}if(mode){if(mode==='zoom+')cad.scale*=1.3;else if(mode==='zoom-')cad.scale/=1.3;else if(mode==='reset')cad={scale:1,ox:0,oy:0,tool:'pan',layers:{project:true,fact:true,point:true},points:[]};else cad.tool=mode;paintCad()}if(action==='check')check();if(action==='showAnswer')showAnswer();if(action==='done')done();if(action==='speak')speak();if(action==='cadexport')cadExport();if(action==='cadreport')fileDownload('RVS5000_измерения.txt',`Проект: X=60000 Y=45000 мм\\nФакт: X=60018 Y=44988 мм\\nСмещение: 21.63 мм\\nСозданные точки: ${JSON.stringify(cad.points)}`);if(action==='calc'){updateJobs();schedule()}if(action==='baseline'){updateJobs();try{baseline=cpm().duration;schedule()}catch(e){alert(e.message)}}if(action==='report'){updateJobs();report()}});\ndocument.addEventListener('change',e=>{if(e.target.id==='cadproject'){cad.layers.project=e.target.checked;paintCad()}if(e.target.id==='cadfact'){cad.layers.fact=e.target.checked;paintCad()}});\ndocument.addEventListener('pointerdown',e=>{if(e.target.id!=='cad')return;if(cad.tool!=='pan')return;cad.drag={x:e.clientX,y:e.clientY,ox:cad.ox,oy:cad.oy};e.target.setPointerCapture(e.pointerId)});\ndocument.addEventListener('pointermove',e=>{if(e.target.id!=='cad'||!cad.drag)return;const r=$('#cad').getBoundingClientRect();cad.ox=cad.drag.ox+(e.clientX-cad.drag.x)*800/r.width;cad.oy=cad.drag.oy+(e.clientY-cad.drag.y)*500/r.height;paintCad()});\ndocument.addEventListener('pointerup',e=>{if(e.target.id!=='cad')return;if(cad.drag){cad.drag=null;return}cadInteraction(e)});render();\n</script></body></html>","bundle":"<!doctype html><html lang=\"ru\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#14223a\"><title>Инженер с нуля · Мобильная академия</title>\n<style>\n:root{font:16px/1.5 system-ui,-apple-system,'Segoe UI',sans-serif;color:#20304a;background:#f1f4f9;--navy:#14223a;--accent:#2965e8;--muted:#5c6b80;--line:#dce3ed}*{box-sizing:border-box}body{margin:0;padding-bottom:100px}button,input{font:inherit}button{cursor:pointer}button:focus-visible,input:focus-visible{outline:3px solid #f0c55f}header{padding:20px max(18px,calc((100vw - 900px)/2));background:var(--navy);color:white}header small{color:#aebfdf}main{max-width:900px;margin:auto;padding:16px}h1{font-size:25px;line-height:1.15;margin:4px 0}h2{font-size:21px;margin:0 0 8px}h3{font-size:17px}.card{background:white;border:1px solid var(--line);border-radius:19px;padding:19px;margin-bottom:14px;box-shadow:0 3px 10px #192d4910}.muted{color:var(--muted);font-size:14px}.notice{background:#edf3ff;padding:12px;border-radius:12px;color:#274674;font-size:13px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.tile{padding:15px;border:1px solid var(--line);border-radius:13px;background:#fff;text-align:left}.tile b{display:block;font-size:22px}.tile small{color:var(--muted)}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:12px;background:var(--accent);color:#fff;padding:12px 15px;min-height:44px;font-weight:700}.btn.outline{background:#eef3ff;color:#2454ac}.btn.soft{background:#edf1f7;color:#20304a}.btn:disabled{opacity:.5}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.row>*{max-width:100%}.tabs{position:fixed;bottom:0;left:0;right:0;background:white;box-shadow:0 -4px 30px #15223a12;display:flex;justify-content:center;gap:3px;padding:9px 8px calc(10px + env(safe-area-inset-bottom));z-index:4}.tabs button{background:transparent;border:0;border-radius:10px;padding:8px 13px;font-weight:650;color:#58667d;font-size:12px}.tabs button.active{background:#eaf1ff;color:#1451c1}.days{display:grid;grid-template-columns:repeat(auto-fill,minmax(154px,1fr));gap:10px}.day{background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px;text-align:left}.day.done{border-color:#60aa89;background:#f0fff6}.day strong{display:block}.day small{display:block;color:var(--muted);font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.75 system-ui;max-height:450px;overflow:auto;padding:15px;border-radius:12px;background:#f6f8fb;border:1px solid #e7eaf0}details summary{font-weight:650;cursor:pointer;padding:8px 0}.bar{height:8px;border-radius:10px;background:#e4e8ef;overflow:hidden}.bar>div{height:100%;background:#2f75df}.field{display:block;width:100%;min-height:47px;border:1px solid #bac5d8;border-radius:10px;padding:10px;background:white;margin:10px 0}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border-bottom:1px solid var(--line);padding:8px;text-align:left}th{background:#f3f6fa}.scroll{overflow:auto}.pill{display:inline-block;background:#eaf1ff;padding:3px 8px;color:#2252a5;border-radius:999px;font-size:12px}.success{color:#137a4d;font-weight:750}.error{color:#ba2839;font-weight:750}#planchart{width:100%;min-height:125px}.tools button{border:1px solid #bdc8da;border-radius:12px;background:#fff;padding:7px 10px}#cad{width:100%;height:330px;border:1px solid #cad4e2;border-radius:14px;touch-action:none;background:#fbfdff}.stat{background:#eef3ff;border-radius:13px;padding:10px}.stat b{display:block}.full{width:100%}@media(max-width:420px){header{padding:16px}h1{font-size:22px}.card{padding:15px}.grid{grid-template-columns:1fr 1fr}.tabs button{font-size:11px;padding:7px}#cad{height:290px}}\n</style></head><body>\n<header><small>ИНЖЕНЕР С НУЛЯ · ОБУЧЕНИЕ НА ТЕЛЕФОНЕ</small><h1>Мобильная академия инженера</h1><small id=\"subhead\">AutoCAD · Primavera P6 · практические тренажёры</small></header>\n<main><div id=\"view\"></div></main><nav class=\"tabs\" id=\"tabs\"></nav>\n<script>\nconst COURSE_DATA={\"cad\":[{\"day\":1,\"title\":\"Старт: мобильный DWG\",\"goal\":\"Просмотр DWG/DXF, копия файла, безопасное управление видом\",\"explanation\":\"Открой учебный чертёж, сохрани отдельную копию; двумя пальцами измени масштаб, одним — перемести вид.\",\"challenge\":\"Укажи, почему исходник нельзя редактировать без копии.\",\"answer\":\"Редактирование копии сохраняет проверяемый оригинал.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Сделайте копию исходного файла до любого изменения; запишите имя, дату и единицы модели.\",\"mobileSteps\":\"Откройте схему и найдите два центра и четыре угла площадки.\",\"deliverable\":\"Скрин копии и запись исходной единицы измерения.\",\"pitfall\":\"В мобильном приложении набор редактируемых форматов зависит от уровня доступа.\"},{\"day\":2,\"title\":\"Типы объектов и свойства\",\"goal\":\"Слои, окружности, полилинии и их свойства\",\"explanation\":\"Выдели линию и окружность. Запиши слой, центр окружности и геометрический тип.\",\"challenge\":\"Чем окружность отличается от полилинии?\",\"answer\":\"Окружность имеет центр и радиус; полилиния — последовательность вершин.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Скрывайте слои по очереди, не удаляя их; сопоставьте объект, цвет, тип и свойства.\",\"mobileSteps\":\"Для двух линий и окружности составьте таблицу: объект / слой / размер.\",\"deliverable\":\"Три строки таблицы свойств.\",\"pitfall\":\"Цвет объекта не всегда однозначно указывает на его слой.\"},{\"day\":3,\"title\":\"Замеры на чертеже\",\"goal\":\"Длина, радиус, диаметр и угол\",\"explanation\":\"В чертеже-симуляторе измерь расстояние между двумя опорными точками; сравни с контрольными данными.\",\"challenge\":\"В каких единицах построена модель РВС-5000?\",\"answer\":\"В миллиметрах, в масштабе 1:1.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Проверьте масштаб геометрии по известному габариту; затем измерьте прямой отрезок.\",\"mobileSteps\":\"Запишите проектный диаметр резервуара и полученный замер.\",\"deliverable\":\"Таблица двух размеров и единицы мм.\",\"pitfall\":\"Длина на экране в пикселях не равна действительной длине в модели.\"},{\"day\":4,\"title\":\"Площадь и периметр\",\"goal\":\"Простые контуры, замкнутые границы\",\"explanation\":\"Определи площадь площадки 120×90 м и периметр.\",\"challenge\":\"Площадь площадки, м²\",\"answer\":10800,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Установите, замкнута ли граница; площадь разомкнутой полилинии ненадёжна.\",\"mobileSteps\":\"Вычислите площадь прямоугольника 120 м на 90 м и кольца как разность площадей кругов.\",\"deliverable\":\"Площадь площадки 10800 м²; список формул.\",\"pitfall\":\"Смешение мм² и м² создаёт ошибку масштаба в миллион раз.\"},{\"day\":5,\"title\":\"Координаты X/Y\",\"goal\":\"Проектные и фактические координаты\",\"explanation\":\"Найди проектный центр (60000;45000) и фактический (60018;44988) мм.\",\"challenge\":\"Отклонение центра по X, мм\",\"answer\":18,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"У координат есть порядок X/Y; проектные и фактические точки не смешивайте.\",\"mobileSteps\":\"Впишите фактический X и Y центра в журнал измерений, затем найдите приращения.\",\"deliverable\":\"ΔX=18 мм, ΔY=-12 мм.\",\"pitfall\":\"Отрицательное отклонение Y нельзя превращать в положительное.\"},{\"day\":6,\"title\":\"Точные геометрические построения\",\"goal\":\"Линия, круг, полилиния, привязка к координатам\",\"explanation\":\"В CAD-полигоне добавь точку и круг, используя координаты; сравни радиус основания.\",\"challenge\":\"Проектный радиус фундамента, мм\",\"answer\":12000,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Построение ведите в одной принятой системе единиц и координат.\",\"mobileSteps\":\"Создайте точку в учебном CAD-полигоне и сопоставьте номинальный радиус 12000 мм.\",\"deliverable\":\"Список созданных геометрических объектов.\",\"pitfall\":\"Рисовать от руки по визуальному масштабу недостаточно для исполнительных схем.\"},{\"day\":7,\"title\":\"Редактирование геометрии\",\"goal\":\"Перемещение, обрезка и исправление\",\"explanation\":\"Создай отдельную ревизию контура; измени положение учебной точки и сравни изменения.\",\"challenge\":\"Почему нельзя исправлять факт прямо на проектном слое?\",\"answer\":\"Смешение слоёв уничтожит возможность проверить отклонения.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"При правке одной геометрии сохраняйте исходник, новое состояние и причину правки.\",\"mobileSteps\":\"Обозначьте перемещённую точку и укажите величину сдвига по двум осям.\",\"deliverable\":\"Запись Rev A и скрин до/после.\",\"pitfall\":\"Изменение факта ради соответствия проекту недопустимо.\"},{\"day\":8,\"title\":\"Слои проект/факт\",\"goal\":\"Отдельные видимость и названия\",\"explanation\":\"Включи только проектный слой; затем только фактический. Оцени изменение положения центра.\",\"challenge\":\"Какой слой хранит измеренные координаты?\",\"answer\":\"Фактический (исполнительный) слой.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Создайте соглашение о названиях слоёв и отдельную таблицу видимости.\",\"mobileSteps\":\"По очереди выключите проект/факт в CAD-полигоне и запишите отличия.\",\"deliverable\":\"Два скрина с переключёнными слоями.\",\"pitfall\":\"Скрытый слой не означает, что его объектов нет в файле.\"},{\"day\":9,\"title\":\"Размеры и выноски\",\"goal\":\"Линейные и диаметральные размеры\",\"explanation\":\"Подготовь размерную выноску: X-факт, Y-факт, смещение центра и диаметр.\",\"challenge\":\"Отклонение центра по Y, мм\",\"answer\":-12,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Выноска должна показывать значение и единицу, а не только графический символ.\",\"mobileSteps\":\"Подпишите проектную и фактическую координату центра и посчитайте разность.\",\"deliverable\":\"Размерная таблица проекта и факта.\",\"pitfall\":\"Не считайте размерную надпись гарантией актуальности самой геометрии.\"},{\"day\":10,\"title\":\"Повторяющиеся элементы\",\"goal\":\"Блоки и 24 анкерных болта\",\"explanation\":\"На схеме размести болты по окружности, найди угловой шаг при 24 равномерно расположенных точках.\",\"challenge\":\"Угловой шаг болтов, градусы\",\"answer\":15,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Одинаковые элементы сначала типизируют, затем нумеруют и контролируют экземпляры.\",\"mobileSteps\":\"Разделите полный круг на 24 шага и оформите список первых четырёх углов.\",\"deliverable\":\"0°, 15°, 30°, 45°; всего 24 позиции.\",\"pitfall\":\"Полярное размещение условно, фактические замеры болтов индивидуальны.\"},{\"day\":11,\"title\":\"Листы и основная надпись\",\"goal\":\"Рамка A3 и реквизиты\",\"explanation\":\"Сформируй в мобильном блокноте титул: шифр объекта, номер листа, ревизию, дату и масштаб.\",\"challenge\":\"Какой формат листа выбран в учебном проекте?\",\"answer\":\"A3.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Лист и модель — разные представления. В основной надписи нужны идентификаторы документа.\",\"mobileSteps\":\"Заполните условный штамп A3, номер листа, дату, ревизию, обозначение учебного проекта.\",\"deliverable\":\"Электронный титульный блок.\",\"pitfall\":\"Неправильная ревизия разрушает трассируемость исполнительной документации.\"},{\"day\":12,\"title\":\"Масштаб и PDF\",\"goal\":\"Разница между моделью и листом\",\"explanation\":\"Проверь единицы модели 1:1 и целевой масштаб листа перед выпуском PDF.\",\"challenge\":\"Геометрию модели нужно уменьшать под лист?\",\"answer\":\"Нет, модель остаётся 1:1, масштаб задаётся в видовом экране/при печати.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Геометрию храните 1:1, масштаб выбирайте для печати, а не для исправления размеров.\",\"mobileSteps\":\"Проверьте на бумажном плане, читаются ли тексты и размеры при выбранном масштабе.\",\"deliverable\":\"Схема модели и выбранный масштаб листа.\",\"pitfall\":\"Не увеличивайте диаметр фактического фундамента ради красивого вывода.\"},{\"day\":13,\"title\":\"Внешние ссылки\",\"goal\":\"XREF и ссылочная целостность\",\"explanation\":\"Составь перечень всех файлов, на которые ссылается чертёж, проверь относительные пути.\",\"challenge\":\"Почему важно проверять потерянные ссылки?\",\"answer\":\"Пользователь может не увидеть часть исходной геометрии.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Внешняя ссылка зависит от местоположения исходного файла.\",\"mobileSteps\":\"Составьте список DWG, PDF и прочих подложек с относительными путями.\",\"deliverable\":\"Таблица ссылок, статуса загрузки и версии.\",\"pitfall\":\"Абсолютные пути с чужого ПК часто не работают.\"},{\"day\":14,\"title\":\"Логика исполнительной схемы\",\"goal\":\"Проект → Факт → Отклонение\",\"explanation\":\"Построй таблицу из проектной и фактической координаты, рассчитывая ΔX и ΔY.\",\"challenge\":\"Как вычислить ΔX?\",\"answer\":\"X факт минус X проект.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Исполнительная схема подтверждает измеренный факт, а не просто переносит проект.\",\"mobileSteps\":\"На четырёх точках сравните проектные/фактические координаты и зафиксируйте разницы.\",\"deliverable\":\"Таблица проект — факт — отклонение.\",\"pitfall\":\"Без даты измерения и основания нельзя утверждать фактическое положение.\"},{\"day\":15,\"title\":\"Схема фундамента\",\"goal\":\"Смещение центра, диаметры и отметки\",\"explanation\":\"Выполни расчёт смещения центра по результатам измерений (18 мм; −12 мм).\",\"challenge\":\"Модуль смещения центра, мм (2 знака)\",\"answer\":21.63,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Смещение в плане считайте как геометрическую длину вектора отклонения.\",\"mobileSteps\":\"По (ΔX;ΔY)=(18;-12) мм найдите √(18²+12²) и округлите до сотых.\",\"deliverable\":\"21,63 мм и показанные промежуточные вычисления.\",\"pitfall\":\"Учебный допуск нельзя выдавать за нормативный допуск строительства.\"},{\"day\":16,\"title\":\"Анкерные болты\",\"goal\":\"Нумерация и таблица отклонений\",\"explanation\":\"Составь журнал 24 анкеров: номер, номинальный угол, фактическое смещение, оценка по условным правилам.\",\"challenge\":\"Количество анкеров\",\"answer\":24,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Каждому болту нужен свой идентификатор; общий круг — лишь проектный ориентир.\",\"mobileSteps\":\"Сформируйте таблицу болтов Б01–Б24 и углов с шагом 15°.\",\"deliverable\":\"24 уникальных номера, первый угол 0°, последний 345°.\",\"pitfall\":\"Проверка одного болта не заменяет проверку всех 24.\"},{\"day\":17,\"title\":\"Площадка и дорога\",\"goal\":\"Поперечные размеры и координаты углов\",\"explanation\":\"На базе учебной площадки найди два габаритных размера и зафиксируй фактический замер.\",\"challenge\":\"Длина площадки, м\",\"answer\":120,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Проверяйте габариты, положение осей и привязку к координатной основе.\",\"mobileSteps\":\"Выпишите габариты 120×90 м, площадь, четыре вершины учебной площадки.\",\"deliverable\":\"Четыре пары координат и габаритный контроль.\",\"pitfall\":\"Длину в мм нельзя писать в отчёте как метры без пересчёта.\"},{\"day\":18,\"title\":\"Ось трубопровода\",\"goal\":\"Изломы, отметки, длины\",\"explanation\":\"Создай полилинию по заданным точкам и рассчитай сумму длин её отрезков.\",\"challenge\":\"Как считается общая длина полилинии?\",\"answer\":\"Сумма длин всех последовательных сегментов.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Длину ломаной считают по сегментам, а не только по расстоянию между крайними точками.\",\"mobileSteps\":\"Постройте маршрут из трёх узлов, сложите длины двух звеньев.\",\"deliverable\":\"Координаты точек, две длины, итог.\",\"pitfall\":\"Прямая между началом и концом часто короче трассы.\"},{\"day\":19,\"title\":\"Ревизии и redline\",\"goal\":\"Журнал изменений и согласования\",\"explanation\":\"Заполни запись Rev B: причина, затронутые листы, дата, статус согласования.\",\"challenge\":\"Зачем хранить журнал ревизий?\",\"answer\":\"Чтобы проследить, кем, когда и почему изменена документация.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Каждая ревизия должна иметь входное изменение и указание затронутых листов.\",\"mobileSteps\":\"Составьте карточку изменения: инициатор, причина, объект, проверка, согласование.\",\"deliverable\":\"Rev A/B и таблица затронутых работ.\",\"pitfall\":\"Без фиксации изменения невозможно доказать актуальность листа.\"},{\"day\":20,\"title\":\"Контроль качества\",\"goal\":\"Дубли, разрывы, слои, единицы\",\"explanation\":\"Пройди 7 контрольных пунктов: открытие, координаты, единицы, слои, размеры, ссылки, оформление.\",\"challenge\":\"Что проверяют перед выпуском документации?\",\"answer\":\"Геометрию, единицы, полноту ссылок, реквизиты, согласования и ревизии.\",\"answerType\":\"text\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"Контроль качества охватывает геометрию, документы, оформление и след ссылок.\",\"mobileSteps\":\"Выполните контрольный лист из семи пунктов; отметьте замечание и ответственного.\",\"deliverable\":\"QA-лист, 7 проверок, исправленные замечания.\",\"pitfall\":\"Автоматическая очистка может удалить нужные объекты — делайте копию.\"},{\"day\":21,\"title\":\"Итоговый проект\",\"goal\":\"Исполнительная схема и портфолио\",\"explanation\":\"Собери учебный отчёт: схему, таблицу проект/факт, ΔX, ΔY, итоговый расчёт, титул и журнал изменений.\",\"challenge\":\"Смещение центра в мм, до 2 знаков\",\"answer\":21.63,\"answerType\":\"number\",\"source\":\"Авторская мобильная адаптация программы RVS5000-EXEC-CAD-TRN v2.0; примеры и значения учебные\",\"concept\":\"В портфолио включайте только собственный учебный результат и пояснение расчётов.\",\"mobileSteps\":\"Соберите 1 лист A3, таблицу отклонений, журнал изменений и краткую защиту.\",\"deliverable\":\"Итоговая учебная исполнительная схема, PDF и отчёт.\",\"pitfall\":\"Учебный пример не подтверждает соответствие реального объекта нормативам.\"}],\"p6\":[{\"day\":1,\"title\":\"День 1. Среда P6, единицы измерения и структура данных Цель дня. Понимать, где в P6 находятся EPS, OBS, Projects, WBS и Activities; настроит\",\"goal\":\"Понимать, где в P6 находятся EPS, OBS, Projects, WBS и Activities; настроить отображение дат и длительностей.\",\"full\":\"День 1. Среда P6, единицы измерения и структура\\nданных\\n  Цель дня. Понимать, где в P6 находятся EPS, OBS, Projects, WBS и Activities; настроить\\n  отображение дат и длительностей.\\n\\nЧто нужно понять\\n  EPS - иерархия портфеля и проектов. OBS - ответственность и доступ. Project - контейнер графика. WBS -\\n   декомпозиция результата. Activity - планируемая работа или веха.\\n  Data Date разделяет фактическое прошлое и прогнозное будущее. Planned Start не заменяет корректный\\n   CPM-расчет.\\n  До ввода данных закрепите единицы: часы в дне, дни в неделе, формат дат, валюту и локальные\\n   настройки.\\n\\nПрактика в P6\\n1. Откройте P6 и сохраните отдельный учебный layout.\\n2. Проверьте User Preferences: Time Units, Dates, Currency, Assistance.\\n3. Создайте EPS-узел TRAINING и проект RVS5000-TRN с Planned Start 07.09.2026 08:00.\\n4. Назначьте Data Date равной старту проекта.\\n\\nКонтроль результата\\n  Доказательство. Скрин проекта в Projects и окно Activities с колонками Activity ID, Name, Original\\n  Duration, Start, Finish, Total Float.\\n\\n  Типичная ошибка. Начинать ввод операций, не проверив часы/день и формат календаря: затем\\n  длительности и трудозатраты выглядят неправильно.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Выберите корректную иерархию данных.\",\"answer\":\"EPS → Project → WBS → Activity\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":2,\"title\":\"День 2. Календари: офис, площадка, смена и непрерывные процессы Цель дня. Создать четыре календаря проекта и понять, как календарь меняет да\",\"goal\":\"Создать четыре календаря проекта и понять, как календарь меняет дату окончания.\",\"full\":\"День 2. Календари: офис, площадка, смена и\\nнепрерывные процессы\\n  Цель дня. Создать четыре календаря проекта и понять, как календарь меняет дату окончания.\\n\\nЧто нужно понять\\n  Календарь определяет рабочие интервалы, выходные и исключения. Одинаковые «5 дней» на 5x8 и 7x12\\n   заканчиваются в разные даты.\\n  Для проекта используются CAL-5X8, CAL-6X10, CAL-7X12 и CAL-24X7. Непрерывный календарь применен\\n   только там, где процесс действительно не прерывается.\\n  Не маскируйте ускорение изменением Hours/Day. Смена календаря - управленческое решение, которое\\n   должно быть видно в графике.\\n\\nПрактика в P6\\n1. Создайте календари по листу Calendars мастер-файла.\\n2. Добавьте праздники и проверьте рабочие интервалы в Workweek и Exceptions.\\n3. Создайте четыре тестовые операции по 5 дней на разных календарях и выполните F9.\\n4. Сравните Start/Finish и удалите тестовые операции.\\n\\nКонтроль результата\\n  Доказательство. Четыре календаря и краткая таблица сравнения окончания тестовых операций.\\n\\n  Типичная ошибка. Назначать 24x7 всем работам ради ранней даты. Это создает нереалистичный\\n  прогноз и скрывает потребность в сменах.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"При разных календарях 5 дней означают одинаковую календарную длительность?\",\"answer\":\"Нет, результат зависит от рабочего календаря.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":3,\"title\":\"День 3. WBS, Activity ID и кодирование графика Цель дня. Создать управляемую WBS и правила идентификации операций.\",\"goal\":\"Создать управляемую WBS и правила идентификации операций.\",\"full\":\"День 3. WBS, Activity ID и кодирование графика\\n  Цель дня. Создать управляемую WBS и правила идентификации операций.\\n\\nЧто нужно понять\\n  WBS отвечает на вопрос «какой результат/часть объекта», а Activity Code - «какой тип, дисциплина, фронт\\n   или пакет». Не превращайте WBS в список исполнителей.\\n  Activity ID должен быть уникальным, коротким и стабильным. В проекте применены префиксы PM, ENG,\\n   PRC, MOB, CIV, FAB, ERT, MEC, ELC, COA, TST, HND.\\n  Для фильтров нужны коды Discipline, Phase, Area, Workfront, Contract Package и Responsible.\\n\\nПрактика в P6\\n1. Создайте корень RVS5000 и 12 дочерних WBS по мастер-файлу.\\n2. Создайте проектные Activity Codes: Discipline, Phase, Area, Workfront, Contract Package.\\n3. Создайте первые 20 операций вручную, соблюдая Activity ID.\\n4. Сгруппируйте Activities по WBS и сохраните layout RVS_01_WBS.\\n\\nКонтроль результата\\n  Доказательство. WBS из 13 узлов и 20 операций в правильных разделах.\\n\\n  Типичная ошибка. Менять Activity ID после выпуска baseline без необходимости: разрушается\\n  сопоставление с отчетами и импортами.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Что обычно является стабильным идентификатором операции?\",\"answer\":\"Activity ID.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":4,\"title\":\"День 4. Операции, вехи, LOE и виды процента выполнения Цель дня. Выбирать Activity Type и Percent Complete Type осознанно.\",\"goal\":\"Выбирать Activity Type и Percent Complete Type осознанно.\",\"full\":\"День 4. Операции, вехи, LOE и виды процента\\nвыполнения\\n  Цель дня. Выбирать Activity Type и Percent Complete Type осознанно.\\n\\nЧто нужно понять\\n  Task Dependent рассчитывается по календарю операции. Resource Dependent - по календарям\\n   назначенных ресурсов. Для учебного строительного графика основной тип - Task Dependent.\\n  Start/Finish Milestone имеют нулевую длительность. Level of Effort тянется между управляющими связями и\\n   не должен задавать критический путь.\\n  Duration % подходит для работ, где прогресс связан с оставшейся длительностью; Physical % - для\\n   измеримого физического результата; Units % - для производительности по трудозатратам.\\n\\nПрактика в P6\\n1. Импортируйте или внесите операции из листа Activities/CSV.\\n2. Проверьте 6 LOE, стартовую и финишную вехи, 0-дневные milestones.\\n3. Для земляных/монтажных работ задайте Physical, для офисных - Duration, для массовых\\n   трудозатратных работ - Units там, где это обосновано.\\n4. Добавьте Steps для операции ERT-0050 и назначьте веса шагов.\\n\\nКонтроль результата\\n  Доказательство. 183 операции, типы и проценты выполнения без случайных значений.\\n\\n  Типичная ошибка. Считать физический прогресс по времени автоматически. 50% длительности не\\n  обязательно означает 50% выполненного объема.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Какая веха имеет нулевую длительность?\",\"answer\":\"Start или Finish Milestone.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":5,\"title\":\"День 5. Логика связей и первый CPM-расчет Цель дня. Построить замкнутую сеть без открытых концов и выполнить Schedule.\",\"goal\":\"Построить замкнутую сеть без открытых концов и выполнить Schedule.\",\"full\":\"День 5. Логика связей и первый CPM-расчет\\n  Цель дня. Построить замкнутую сеть без открытых концов и выполнить Schedule.\\n\\nЧто нужно понять\\n  FS - следующая работа начинается после окончания предыдущей. SS - работы стартуют совместно или с\\n   заданным смещением. FF - совместное окончание. SF применяется редко.\\n  Лаг не объясняет работу. Где возможно, заменяйте лаг отдельной операцией: выдержка бетона, доставка,\\n   проверка, согласование.\\n  Каждая обычная операция должна иметь логического предшественника и последователя; исключения -\\n   контрольные вехи и обоснованные LOE.\\n\\nПрактика в P6\\n1. Загрузите 240 связей или создайте минимум один полный участок вручную: фундамент -> днище ->\\n   стенка -> крыша -> испытание.\\n2. Выполните Tools > Schedule (F9), включите Log to File.\\n3. Проверьте Data Date, открытые концы, логику progress override/retained logic и календарь лагов.\\n4. Сохраните Schedule Log в папку проекта.\\n\\nКонтроль результата\\n  Доказательство. График рассчитан, одна стартовая и одна финишная точка, 0 отрицательных\\n  лагов.\\n\\n  Типичная ошибка. Соединять работы только потому, что они расположены рядом в списке. Связь\\n  должна отражать технологическую или управленческую зависимость.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Если операции А (4 дня) → B (6 дней), сколько длится цепочка FS без лагов? \",\"answer\":10,\"answerType\":\"number\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":6,\"title\":\"День 6. Ограничения, float, longest path и критический путь Цель дня. Отличать расчетную логику от искусственно заданных дат.\",\"goal\":\"Отличать расчетную логику от искусственно заданных дат.\",\"full\":\"День 6. Ограничения, float, longest path и критический\\nпуть\\n  Цель дня. Отличать расчетную логику от искусственно заданных дат.\\n\\nЧто нужно понять\\n  Total Float показывает допустимый сдвиг до выбранной контрольной даты с учетом текущей сети. Free\\n   Float - сдвиг без влияния на ранний старт непосредственного последователя.\\n  Критический путь лучше анализировать как longest path, а не только по цвету «Total Float <= 0».\\n  Hard constraints могут скрыть причинно-следственную связь. В учебном проекте оставлены только\\n   контроль старта и контрактного финиша.\\n\\nПрактика в P6\\n1. Добавьте колонки Total Float, Free Float, Longest Path, Primary Constraint, Constraint Date.\\n2. Запустите F9 с Calculate Multiple Float Paths и отметьте 19 операций longest path.\\n3. Создайте фильтры Critical и Near Critical (например, TF <= 10 рабочих дней).\\n4. Временно задайте Must Finish By на слишком раннюю дату, увидьте negative float, затем удалите\\n   учебное ограничение.\\n\\nКонтроль результата\\n  Доказательство. Layout RVS_02_CRITICAL с критическими и околокритическими операциями.\\n\\n  Типичная ошибка. «Лечить» отрицательный float ограничениями или ручными датами. Сначала\\n  исправляют логику, производительность и последовательность.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Что может скрывать истинную логику критического пути?\",\"answer\":\"Жёсткие ограничения и ручные даты.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":7,\"title\":\"День 7. Layouts, группировка, фильтры, Activity Codes и UDF Цель дня. Получать разные управленческие представления из одной модели.\",\"goal\":\"Получать разные управленческие представления из одной модели.\",\"full\":\"День 7. Layouts, группировка, фильтры, Activity Codes и\\nUDF\\n  Цель дня. Получать разные управленческие представления из одной модели.\\n\\nЧто нужно понять\\n  Layout - это не отдельный график, а набор колонок, группировок, фильтров, шкалы времени и bars.\\n  Activity Codes подходят для устойчивых классификаторов; UDF - для дополнительных полей, которых нет в\\n   стандартной структуре.\\n  Фильтр должен быть воспроизводим: указывайте условия, порядок AND/OR и сохраняйте название\\n   версии.\\n\\nПрактика в P6\\n1. Создайте layouts: WBS, Critical, 2-Week Lookahead, Procurement, Civil, Tank Erection, Management\\n   Summary.\\n2. Создайте UDF: Quantity, Unit, Drawing No., Delay Reason, Recovery Action.\\n3. Сгруппируйте по Discipline и Responsible; добавьте subtotals по Budgeted Cost.\\n4. Экспортируйте layout в файл или сохраните его как Project layout.\\n\\nКонтроль результата\\n  Доказательство. Минимум 7 layouts и 5 UDF, которые реально используются.\\n\\n  Типичная ошибка. Делать копии проектов для каждого вида отчета. Нужны layouts и filters, а не\\n  параллельные несогласованные графики.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Нужно ли копировать проект ради нового Layout?\",\"answer\":\"Нет, Layout — представление одной модели.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":8,\"title\":\"День 8. Ресурсы, роли, ставки и трудозатраты Цель дня. Загрузить 46 ресурсов и понять Units/Time, Budgeted Units и Cost.\",\"goal\":\"Загрузить 46 ресурсов и понять Units/Time, Budgeted Units и Cost.\",\"full\":\"День 8. Ресурсы, роли, ставки и трудозатраты\\n  Цель дня. Загрузить 46 ресурсов и понять Units/Time, Budgeted Units и Cost.\\n\\nЧто нужно понять\\n  Labor, Nonlabor и Material ведут себя по-разному. Для людей и техники единицы часто выражаются\\n   часами; для материалов - физическими единицами.\\n  Budgeted Units = Units/Time x Duration при линейном распределении. Ставка превращает единицы в\\n   ресурсную стоимость.\\n  Role описывает требуемую компетенцию, Resource - конкретный исполнитель или агрегированный экипаж.\\n\\nПрактика в P6\\n1. Создайте ресурсы вручную или через шаблон: руководство, инженеры, бригады, техника, материалы.\\n2. Проверьте Resource ID, Type, Calendar, Max Units/Time и Price/Unit.\\n3. Назначьте ресурсы минимум на 25 операций вручную, затем загрузите остальные назначения.\\n4. Откройте Resource Usage Profile и Resource Usage Spreadsheet.\\n\\nКонтроль результата\\n  Доказательство. 46 ресурсов, 221 назначение, учебная ресурсная стоимость 167 413 200 ₽.\\n\\n  Типичная ошибка. Путать количество людей с трудозатратами. 10 сварщиков по 10 часов - это 100\\n  человеко-часов за смену.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"6 работников по 8 часов ежедневно дают сколько чел.-ч в день?\",\"answer\":48,\"answerType\":\"number\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":9,\"title\":\"День 9. Перегрузка, профили и ресурсное выравнивание Цель дня. Найти конфликт ресурсов и сделать осознанный recovery-план.\",\"goal\":\"Найти конфликт ресурсов и сделать осознанный recovery-план.\",\"full\":\"День 9. Перегрузка, профили и ресурсное выравнивание\\n  Цель дня. Найти конфликт ресурсов и сделать осознанный recovery-план.\\n\\nЧто нужно понять\\n  Гистограмма показывает спрос по времени. Перегрузка не всегда означает ошибку: сначала проверяют\\n   Max Units/Time, календарь и параллельность.\\n  Resource Leveling меняет даты на основании приоритетов и доступности. До запуска сделайте копию или\\n   baseline и задайте правила.\\n  В строительном графике выравнивание не заменяет производственный анализ фронтов, сменности и\\n   техники.\\n\\nПрактика в P6\\n1. Найдите пиковую загрузку сварочной бригады и крана 90 т.\\n2. Создайте сценарий: ограничьте доступность сварщиков, выполните Level Resources и сравните finish.\\n3. Верните исходный график и создайте recovery: вторая смена или параллельный фронт.\\n4. Зафиксируйте разницу в Change Log.\\n\\nКонтроль результата\\n  Доказательство. До/после: ресурсный профиль, дата окончания и объяснение принятого решения.\\n\\n  Типичная ошибка. Нажимать Level Resources с настройками по умолчанию и принимать новую дату\\n  без проверки логики.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Что означает выравнивание ресурсов?\",\"answer\":\"Устранение перегрузок путём перестройки загрузки и/или дат.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":10,\"title\":\"День 10. Expenses, Cost Accounts и базовый план Цель дня. Сформировать полный бюджет и зафиксировать baseline.\",\"goal\":\"Сформировать полный бюджет и зафиксировать baseline.\",\"full\":\"День 10. Expenses, Cost Accounts и базовый план\\n  Цель дня. Сформировать полный бюджет и зафиксировать baseline.\\n\\nЧто нужно понять\\n  Resource Cost связан с назначениями. Expense нужен для закупок, услуг, логистики и иных затрат, которые\\n   нецелесообразно моделировать ресурсом.\\n  Baseline - снимок утвержденного плана. Он нужен для сравнения Start/Finish, Duration, Units и Cost.\\n  После утверждения baseline нельзя тихо переписывать. Изменение проходит через Change Log и\\n   согласование.\\n\\nПрактика в P6\\n1. Загрузите 12 расходов общей стоимостью 109 100 000 ₽.\\n2. Создайте Cost Accounts по разделам: Engineering, Procurement, Civil, Tank, Mechanical, E&I, Coating,\\n   Commissioning, PM.\\n3. Project > Maintain Baselines: создайте BL1 Approved Baseline.\\n4. Project > Assign Baselines: назначьте BL1 как Project Primary Baseline и включите baseline bars.\\n\\nКонтроль результата\\n  Доказательство. Общий бюджет 276 513 200 ₽ и отображение baseline bars/variance columns.\\n\\n  Типичная ошибка. Создать baseline после внесения фактического прогресса или задержек. Сначала\\n  фиксируется утвержденный план.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Для чего фиксируется Baseline?\",\"answer\":\"Для сравнения фактического состояния и текущего прогноза с утверждённым планом.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":11,\"title\":\"День 11. Обновление по факту: Data Date, actuals и remaining duration Цель дня. Правильно внести Update 1 и Update 2 и получить прогноз.\",\"goal\":\"Правильно внести Update 1 и Update 2 и получить прогноз.\",\"full\":\"День 11. Обновление по факту: Data Date, actuals и\\nremaining duration\\n  Цель дня. Правильно внести Update 1 и Update 2 и получить прогноз.\\n\\nЧто нужно понять\\n  Actual Start/Finish - факты. Remaining Duration - оценка оставшегося времени. Physical % - измеренный\\n   объем. Эти поля нельзя подменять друг другом.\\n  Data Date переносится на отчетную дату до запуска F9. Операции в прошлом без actuals и будущие actuals\\n   требуют разбирательства.\\n  Retained Logic сохраняет незавершенную логику; Progress Override может разрешить фактическую работу\\n   вопреки предшественникам. Выбор должен быть осознан.\\n\\nПрактика в P6\\n1. Сделайте копию текущего проекта или сохраните layout и baseline.\\n2. Установите Data Date 05.10.2026, внесите UPDATE_01, выполните F9.\\n3. Сравните BL Start/Finish, Start/Finish Variance, Total Float и критический путь.\\n4. Повторите для Data Date 02.11.2026 и оформите недельный комментарий.\\n\\nКонтроль результата\\n  Доказательство. Два обновления с сохраненными Schedule Log и отчетом причин отклонения.\\n\\n  Типичная ошибка. Проставлять Percent Complete без Actual Start или оставлять завершенную\\n  операцию без Actual Finish.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Data Date отделяет что?\",\"answer\":\"Фактическое прошлое от расчётного будущего.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":12,\"title\":\"День 12. Обновления 3-6, прогноз и recovery Цель дня. Проследить, как задержка поставки и сварки меняет критический путь.\",\"goal\":\"Проследить, как задержка поставки и сварки меняет критический путь.\",\"full\":\"День 12. Обновления 3-6, прогноз и recovery\\n  Цель дня. Проследить, как задержка поставки и сварки меняет критический путь.\\n\\nЧто нужно понять\\n  Прогноз должен отражать реальную производительность, а не желаемую дату. Remaining Duration\\n   пересматривается по факту выработки.\\n  Recovery-план документирует конкретные меры: дополнительная смена, изменение последовательности,\\n   ускоренная поставка, разделение фронта.\\n  После каждой меры проверяйте безопасность, технологию, ресурсную загрузку и изменение бюджета.\\n\\nПрактика в P6\\n1. Последовательно внесите Update 3-6 из папки 04_ОБНОВЛЕНИЯ_ПО_ФАКТУ.\\n2. На Update 4 найдите влияние ремонта сварных швов; на Update 5 смоделируйте вторую смену.\\n3. Сравните Forecast Finish до и после recovery, а также ресурсный пик и стоимость.\\n4. Внесите решение в Delay Register и Change Log.\\n\\nКонтроль результата\\n  Доказательство. Таблица шести Data Date: Forecast Finish, variance, критический участок, действие\\n  и владелец.\\n\\n  Типичная ошибка. Восстанавливать срок простым уменьшением Remaining Duration без\\n  производственного обоснования.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"После изменения длительности работы необходимо что?\",\"answer\":\"Пересчитать график и проверить влияние на критический путь.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":13,\"title\":\"День 13. Earned Value, S-curve, look-ahead и недельный отчет Цель дня. Перевести данные графика в управленческий отчет.\",\"goal\":\"Перевести данные графика в управленческий отчет.\",\"full\":\"День 13. Earned Value, S-curve, look-ahead и недельный\\nотчет\\n  Цель дня. Перевести данные графика в управленческий отчет.\\n\\nЧто нужно понять\\n  PV - стоимость запланированной работы к Data Date. EV - бюджетная стоимость фактически выполненного\\n   объема. AC - фактическая стоимость.\\n  SPI = EV / PV; CPI = EV / AC. Значения меньше 1 показывают отставание по сроку или перерасход\\n   относительно выполненного объема.\\n  S-curve должна использовать time-distributed данные, а не равномерно размазанный итоговый бюджет без\\n   оснований.\\n\\nПрактика в P6\\n1. Назначьте baseline для EV и проверьте настройки Earned Value Calculation.\\n2. Заполните S_Curve в книге Шаблоны_планировщика_P6.xlsx.\\n3. Сформируйте 2-недельный look-ahead от Data Date.\\n4. Заполните Weekly Report: план/факт, SPI/CPI, критический путь, top risks, решения.\\n\\nКонтроль результата\\n  Доказательство. S-curve, look-ahead и недельный отчет на одну выбранную Data Date.\\n\\n  Типичная ошибка. Использовать SPI/CPI без проверки качества baseline, фактических затрат и\\n  правила начисления прогресса.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"SPI=0,8 означает опережение графика?\",\"answer\":\"Нет, по этому показателю освоенная стоимость ниже плановой.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"},{\"day\":14,\"title\":\"День 14. QA графика, итоговый экзамен и выпуск пакета планировщика Цель дня. Самостоятельно проверить график и защитить принятые решения.\",\"goal\":\"Самостоятельно проверить график и защитить принятые решения.\",\"full\":\"День 14. QA графика, итоговый экзамен и выпуск пакета\\nпланировщика\\n  Цель дня. Самостоятельно проверить график и защитить принятые решения.\\n\\nЧто нужно понять\\n  Хороший график - это не красивая диаграмма Ганта, а проверяемая сеть с понятными календарями,\\n   ресурсами, baseline, actuals и прогнозом.\\n  Перед выпуском фиксируют Data Date, Schedule Options, Schedule Log, change history и версию файла.\\n  Любое отклонение должно иметь причину, влияние, действие, владельца и срок решения.\\n\\nПрактика в P6\\n1. Выполните чек-лист Schedule_QA из мастер-файла.\\n2. Сдайте практический экзамен из отдельного документа.\\n3. Соберите выпуск: график, Schedule Log, 2W look-ahead, weekly report, S-curve, risk/delay/change\\n   registers.\\n4. Защитите критический путь и recovery-план устно за 10 минут.\\n\\nКонтроль результата\\n  Доказательство. Полный комплект отчетности и результат экзамена не ниже 80%.\\n\\n  Типичная ошибка. Заканчивать работу после F9. Расчет - только начало анализа, проверки и\\n  объяснения прогноза.\\n\\n  ☐ Результат сохранен отдельной версией или подтвержден скрином.\\n  ☐ В трекере проставлен статус и самооценка.\\n  ☐ Непонятные термины добавлены в личный словарь.\\n  ☐ Критическая ошибка устранена до следующего дня.\\n\\n    4. ПРОФЕССИОНАЛЬНАЯ ПРАКТИКА\\n                  Как читать и защищать график, а не только вводить данные\\n\\n4.1. Правила качественной логики\\n  Связь должна описывать реальное технологическое, контрактное или информационное условие.\\n  Используйте FS по умолчанию только тогда, когда работа действительно не может стартовать раньше\\n   полного окончания предшественника.\\n  SS/FF применяйте для параллельных процессов, но проверяйте, что сеть не создает невозможный\\n   прогноз.\\n  Заменяйте длительный lag отдельной операцией с названием, ответственным и календарем.\\n  Не оставляйте обычные операции без предшественников/последователей.\\n  Не используйте constraints для сокрытия отсутствующей логики.\\n\\nМини-задача: объяснить участок монтажа\\n                   ID                                     Операция                                     Предшественники\\n\\nCIV-0190                                 Приемка фундамента под монтаж резервуара        CIV-0180 FS\\n\\n                                         Разложить и рассортировать листы на\\nERT-0020                                                                                 FAB-0110 FS, ERT-0010 FS\\n                                         площадке\\n\\nERT-0030                                 Разметить и уложить листы днища                 ERT-0020 FS\\n\\nERT-0040                                 Сборка и сварка окраек днища                    ERT-0030 FS\\n\\nERT-0050                                 Сборка и сварка центральной части днища         ERT-0040 FS\\n\\nERT-0060                                 Вакуумный контроль швов днища                   PRC-0130 FS, ERT-0050 FS\\n\\nERT-0070                                 Сборка первого пояса стенки                     ERT-0060 FS\\n\\nERT-0080                                 Сварка первого пояса стенки                     ERT-0070 FS\\n\\nERT-0090                                 НК первого пояса стенки                         ERT-0080 FS\\n\\nERT-0100                                 Сборка второго пояса стенки                     ERT-0090 FS\\n\\nERT-0110                                 Сварка второго пояса стенки                     ERT-0100 FS\\n\\nERT-0120                                 НК второго пояса стенки                         ERT-0110 FS\\n\\n4.2. Schedule Options и Schedule Log\\nСохраняйте настройки расчета вместе с версией графика. Одинаковая сеть при разных options может\\nдать разные даты.\\n  ☐ Data Date соответствует отчетному периоду.\\n  ☐ Log to File включен и файл сохранен с датой.\\n  ☐ Проверено правило фактической работы: Retained Logic / Progress Override / Actual Dates.\\n  ☐ Выбран календарь расчета lag.\\n  ☐ Включен расчет нескольких float paths, если нужен анализ near critical.\\n  ☐ Проверены out-of-sequence progress, open ends, constraints, negative float, relationship lags.\\n  ☐ Forecast Finish сопоставлен с контрактным финишем.\\n\\n4.3. Базовый план и управление изменениями\\n                          Событие                                                             Действие\\n\\n                                                                   Создать Approved Baseline, назначить Primary Baseline,\\nПлан согласован\\n                                                                   зафиксировать Schedule Log и PDF/XLSX-выгрузку.\\n\\n                             Событие                                                    Действие\\n\\n                                                             Создать Change Request, добавить/удалить операции и сохранить\\nИзменен объем\\n                                                             влияние на срок/стоимость.\\n\\n                                                             Создать новую baseline-версию или обновить baseline в\\nУтверждено изменение\\n                                                             соответствии с процедурой проекта.\\n\\n                                                             Сохранить baseline, изменить current schedule, показать разницу и\\nRecovery без изменения контракта\\n                                                             ресурсно-стоимостные последствия.\\n\\nНеутвержденная идея                                          Моделировать в копии/what-if, не в официальной версии.\\n\\n4.4. Ресурсный анализ\\n              Тип ресурса                             Количество                              Бюджет назначений\\n\\nLabor                                  31                                          66 627 400 ₽\\n\\nMaterial                               5                                           80 974 000 ₽\\n\\nNonlabor                               10                                          19 811 800 ₽\\n\\n  Сначала проверяйте календарь и Max Units/Time, затем факт перегрузки.\\n  Различайте трудозатраты и численность/единицы техники.\\n  Проверяйте профиль по критическим ресурсам: сварщики, монтажники, кран, NDT, АКЗ.\\n  Любое ускорение должно быть связано с конкретным ресурсным решением.\\n\\n4.5. Earned Value и формулы\\n                Показатель                             Формула                                       Смысл\\n\\n                                                                                   Сколько работы по baseline должно быть\\nPV                                     Плановая стоимость к Data Date\\n                                                                                   выполнено.\\n\\n                                       Бюджетная стоимость выполненного            Сколько бюджетной стоимости заработано\\nEV\\n                                       объема                                      фактом.\\n\\nAC                                     Фактическая стоимость                       Сколько реально потрачено.\\n\\n                                                                                   Отклонение по сроку в стоимостном\\nSV                                     EV - PV\\n                                                                                   выражении.\\n\\nCV                                     EV - AC                                     Отклонение стоимости.\\n\\nSPI                                    EV / PV                                     < 1 - отставание; > 1 - опережение.\\n\\nCPI                                    EV / AC                                     < 1 - перерасход; > 1 - экономия.\\n\\n                                                                                   Прогноз итоговой стоимости при\\nEAC                                    BAC / CPI (один из вариантов)\\n                                                                                   сохранении тенденции.\\n\\n  Осторожно. EV не исправляет плохой baseline, неверные actual costs или формальный Physical %.\\n  Перед интерпретацией индексов проверьте качество исходных данных.\\n\\n                  5. ОБНОВЛЕНИЯ ПО ФАКТУ\\n                          Шесть Data Date, причины отклонений и recovery\\n\\n             Data Date                     Состояние                    Главное отклонение                   Задача анализа\\n\\n                                 Инженерные работы и              Техническая оценка металла +3     Проверить стартовые actuals,\\n05.10.2026\\n                                 мобилизация                      рабочих дня                       baseline variance и Schedule Log.\\n\\n                                                                  Заказ металла и vendor data +5    Пересмотреть Remaining Duration\\n02.11.2026                       Фундамент в работе\\n                                                                  дней                              и прогноз поставки.\\n\\n                                 Фундамент принят, металл                                           Определить влияние на монтаж\\n07.12.2026                                                        Партия 1 прогнозируется +7 дней\\n                                 изготавливается                                                    днища и near-critical path.\\n\\n                                 Партия 1 на площадке, начато     Ремонт сварных швов и поздний     Разделить ремонт, повторный\\n01.02.2027\\n                                 днище                            старт монтажа                     NDT и остаток работ.\\n\\n                                                                                                    Сравнить срок, ресурсный пик и\\n05.04.2027                       Монтаж стенки                    Введена вторая сварочная смена\\n                                                                                                    стоимость recovery.\\n\\n                                                                  Гидроиспытание и внутренняя       Сформировать финальный\\n07.06.2027                       Механическая готовность\\n                                                                  АКЗ определяют финиш              прогноз и план приемки.\\n\\n5.1. Стандартный цикл обновления\\n1. Собрать подтвержденные actuals и остаточные оценки от ответственных.\\n2. Сохранить текущую версию и установить новую Data Date.\\n3. Внести Actual Start/Finish, Remaining Duration, Physical/Units %, Actual Units/Cost.\\n4. Проверить out-of-sequence progress и фактические даты за Data Date.\\n5. Выполнить F9 и сохранить Schedule Log.\\n6. Сравнить baseline и current: milestones, forecast finish, float, critical/near-critical paths.\\n7. Обновить Delay Register, Change Log, Risk Register, 2W look-ahead и weekly report.\\n8. Зафиксировать решения, владельцев и сроки действий.\\n\\n5.2. Как формулировать отклонение\\n                               Поле                                                             Пример\\n\\n                                                                  Поставка партии листовой стали сдвинута на 7 календарных\\nПричина\\n                                                                  дней.\\n\\n                                                                  Старт раскладки днища сдвигается на 5 рабочих дней; float\\nВоздействие\\n                                                                  участка снижается до 2 дней.\\n\\n                                                                  Разделить поставку по партиям, мобилизовать вторую смену\\nДействие\\n                                                                  сварщиков, заранее подготовить laydown.\\n\\nВладелец                                                          Менеджер закупок / начальник участка.\\n\\nСрок решения                                                      До следующей Data Date или конкретная календарная дата.\\n\\n                                                                  Письмо поставщика, обновленный график, ресурсный\\nДоказательство\\n                                                                  профиль, change record.\\n\\n5.3. Recovery-план: что проверять\\n  ☐ Мера связана с конкретной операцией и причиной.\\n  ☐ Новая длительность подтверждена производительностью и ресурсами.\\n  ☐ Календари/смены реалистичны и согласованы.\\n  ☐ Не нарушены HSE, качество, технологическая последовательность и hold points.\\n  ☐ Проверена перегрузка людей и техники.\\n\\n  ☐ Показана дополнительная стоимость.\\n  ☐ Forecast Finish действительно улучшился после F9.\\n  ☐ Изменение отражено в Change Log и weekly report.\\n\\n                       6. КОНТРОЛЬ КАЧЕСТВА\\n                               Проверки перед выпуском каждого графика\\n\\n6.1. Базовый QA-чек-лист\\n                            Проверка                                              Критерий\\n\\nУникальность ID                                     Нет дубликатов Activity ID.\\n\\nОткрытые концы                                      Только обоснованные стартовая/финишная вехи и LOE.\\n\\n                                                    Нет отрицательных lag; положительные минимальны и\\nЛаги\\n                                                    объяснены.\\n\\nConstraints                                         Только необходимые контрольные ограничения.\\n\\nДлительности                                        Длинные операции декомпозированы либо обоснованы.\\n\\nКалендари                                           Каждая операция использует правильный режим работы.\\n\\nФактические даты                                    Нет будущих actuals и незавершенных операций с Actual Finish.\\n\\nData Date                                           Соответствует отчетному периоду.\\n\\nCritical path                                       Путь логичен и заканчивается на контрактной/финишной вехе.\\n\\nNear critical                                       Проверены несколько float paths и ключевые риски.\\n\\nРесурсы                                             Нет необъясненной перегрузки критических ресурсов.\\n\\nBaseline                                            Назначена верная версия и показаны variance columns.\\n\\nСтоимость                                           Resource Costs + Expenses сходятся с контрольным бюджетом.\\n\\n                                                    Schedule Log, look-ahead, S-curve и реестры имеют одну Data\\nОтчетность\\n                                                    Date.\\n\\n6.2. Контрольные цифры комплекта\\n                           Показатель                                             Ожидаемо\\n\\nОпераций                                            183\\n\\nСвязей                                              240\\n\\nРесурсов                                            46\\n\\nНазначений                                          221\\n\\nExpenses                                            12\\n\\nКритических longest path                            19\\n\\nNear critical                                       78\\n\\nОткрытые начала/окончания                           1/1\\n\\nОтрицательные лаги                                  0\\n\\nОграничения                                         2\\n\\nЦиклы                                               0\\n\\nОбщий бюджет                                        276 513 200 ₽\\n\\nБазовый finish                                      2027-12-07 08:00\\n\\nКонтрактный finish                                  2027-12-20 18:00\\n\\n  Допуск различий. После импорта в P6 даты могут немного отличаться из-за календарных\\n  исключений, настроек lag, start/finish rules, time units и способа обработки XML. Объясните различие,\\n  а не подгоняйте числа вручную.\\n\\n6.3. Критерии готовности планировщика\\n                          Уровень                                                 Критерий\\n\\n                                                       Создает проект, WBS, календари, операции и связи; запускает\\nБазовый\\n                                                       F9.\\n\\n                                                       Объясняет critical/float, ведет baseline и actuals, выпускает\\nРабочий\\n                                                       look-ahead.\\n\\n                                                       Анализирует ресурсы, несколько float paths, EV, причины и\\nУверенный\\n                                                       recovery.\\n\\n                                                       За 10 минут защищает структуру графика, критический путь,\\nГотов к собеседованию\\n                                                       обновление и управленческий вывод.\\n\\n                               7. СПРАВОЧНИК\\n                   Термины, последовательности и официальные источники\\n\\n7.1. Мини-глоссарий\\n                           Термин                                                   Определение\\n\\nEPS                                                       Enterprise Project Structure - иерархия проектов/портфеля.\\n\\nOBS                                                       Organizational Breakdown Structure - ответственность и права.\\n\\nWBS                                                       Work Breakdown Structure - декомпозиция результата проекта.\\n\\n                                                          Операция с логикой, длительностью, календарем и\\nActivity\\n                                                          ответственностью.\\n\\nMilestone                                                 Нулевая длительность, контрольное событие.\\n\\n                                                          Level of Effort - поддерживающая работа, растянутая между\\nLOE\\n                                                          связями.\\n\\nData Date                                                 Граница между фактом и прогнозом.\\n\\nBaseline                                                  Зафиксированный утвержденный план для сравнения.\\n\\nOriginal Duration                                         Первоначальная длительность операции.\\n\\nRemaining Duration                                        Оценка времени до завершения незаконченной операции.\\n\\nActual Start/Finish                                       Подтвержденные фактические даты.\\n\\nEarly Start/Finish                                        Самые ранние даты по логике и календарям.\\n\\nLate Start/Finish                                         Самые поздние даты без сдвига выбранного окончания.\\n\\nTotal Float                                               Резерв относительно конечного ограничения/финиша сети.\\n\\n                                                          Резерв без влияния на ранний старт непосредственного\\nFree Float\\n                                                          последователя.\\n\\nLongest Path                                              Цепочка, определяющая расчетное окончание проекта.\\n\\n                                                          Фактическая работа выполнена вопреки логике\\nOut-of-sequence progress\\n                                                          предшественников.\\n\\nResource Leveling                                         Пересчет дат с учетом ограниченной доступности ресурсов.\\n\\nPV / EV / AC                                              Плановая стоимость / освоенный объем / фактическая стоимость.\\n\\nSPI / CPI                                                 Индексы выполнения по сроку / стоимости.\\n\\n7.2. Последовательность действий перед F9\\n1. Проверить открытую версию проекта и Data Date.\\n2. Проверить фактические даты, статусы и Remaining Duration.\\n3. Проверить новые/измененные связи, constraints и calendars.\\n4. Проверить Schedule Options.\\n5. Выполнить F9 с Log to File.\\n6. Открыть log и устранить ошибки/предупреждения.\\n7. Проверить finish, critical/near critical, negative float и ресурсные пики.\\n8. Сохранить версию и выпускные отчеты.\\n\\n7.3. Официальные источники Oracle\\n                                Источник                                                                 Адрес\\n\\n                                                                       https://docs.oracle.com/cd/G48902_01/English/User_Guides/p6_pro_user/\\nP6 Professional User Guide, Version 26\\n                                                                       toc.htm\\n\\nP6 Professional Help, Version 26                                       https://docs.oracle.com/cd/G48902_01/client_help/en_US/toc.htm\\n\\n                                                                       https://docs.oracle.com/cd/G48902_01/English/admin/p6_pro_admin/\\nP6 Professional Administration Guide - import privileges\\n                                                                       48405.htm\\n\\n                                                                       https://docs.oracle.com/en/industries/construction-engineering/primavera-\\nPrimavera P6 Professional documentation landing page\\n                                                                       p6-professional/\\n\\n  Версионность. Пункты меню и доступные поля импорта могут отличаться в разных выпусках и\\n  локализациях. При расхождении ориентируйтесь на Help вашей установленной версии и служебные\\n  заголовки экспортированного XLSX.\\n\\n7.4. Следующий шаг после курса\\nПеренесите навык на второй проект без готового набора: составьте WBS, словарь операций, календари,\\nлогическую схему, ресурсный справочник и правила обновления. Умение повторить процесс на новом\\nобъекте - главный критерий, что Primavera освоена, а не просто заполнен учебный файл.\\n  ☐ Сдать экзамен не ниже 80%.\\n  ☐ Повторить проект с нуля без подсказки.\\n  ☐ Сделать 30-дневное закрепление по трекеру.\\n  ☐ Подготовить 10-минутный рассказ о графике для собеседования.\",\"minutes\":60,\"source\":\"Курс_Primavera_P6_RVS5000.pdf — собственный материал проекта, 21.08.2026\",\"challenge\":\"Что включают в QA графика?\",\"answer\":\"Открытые концы, связи, ограничения, длительности, календари и ресурсы.\",\"answerType\":\"text\",\"phoneTip\":\"На телефоне выполняйте расчёты во встроенном графике; для редактирования исходного расписания в P6 Professional нужен соответствующий программный доступ.\"}]};\nconst PRODUCT_MODE='all';let DATA=COURSE_DATA;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>\"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[x]));\nlet state={section:'home',course:'cad',day:1};let completed=(()=>{try{return JSON.parse(localStorage.getItem('izn_progress_v1')||'{}')}catch{return {}}})();\nfunction save(){try{localStorage.setItem('izn_progress_v1',JSON.stringify(completed))}catch{}}const days=id=>DATA[id]||[];\nfunction render(){const links=[['home','Обзор'],['cad','AutoCAD'],['p6','Primavera'],['drawing','Чертёж'],['schedule','График']].filter(([id])=>PRODUCT_MODE==='all'||(PRODUCT_MODE==='cad'?['home','cad','drawing'].includes(id):['home','p6','schedule'].includes(id)));$('#tabs').innerHTML=links.map(([id,label])=>`<button data-go=\"${id}\" class=\"${state.section===id?'active':''}\">${label}</button>`).join('');\nif(state.section==='home')home();else if(['cad','p6'].includes(state.section))course(state.section);else if(state.section==='lesson')lesson();else if(state.section==='drawing')drawing();else if(state.section==='schedule')schedule();}\nfunction home(){let c=Object.keys(completed).filter(k=>completed[k]&&(PRODUCT_MODE==='all'||k.startsWith(PRODUCT_MODE))).length;const TOTAL=Object.values(DATA).reduce((a,x)=>a+x.length,0);$('#view').innerHTML=`<section class=\"card\"><h2>Учись, выполняй и проверяй</h2><p>Полноценный мобильный учебник с самостоятельными заданиями. Данные сохраняются на устройстве. Все числовые примеры — условный учебный проект РВС-5000.</p><div class=\"grid\"><button class=\"tile\" data-go=\"cad\"><b>21 день</b>AutoCAD<br><small>DWG, размеры, проект/факт</small></button><button class=\"tile\" data-go=\"p6\"><b>14 дней</b>Primavera P6<br><small>WBS, CPM, baseline, план-факт</small></button></div><p class=\"muted\">Пройдено уроков: <b>${c} / ${TOTAL}</b></p><div class=\"bar\"><div style=\"width:${Math.round(c/Math.max(TOTAL,1)*100)}%\"></div></div></section><section class=\"card\"><h2>Работа прямо на телефоне</h2><div class=\"row\"><button class=\"btn outline\" data-go=\"drawing\">Открыть CAD-практику</button><button class=\"btn outline\" data-go=\"schedule\">Открыть CPM-график</button></div><p class=\"notice\">Тренажёры выполняют учебные вычисления и не являются программами Autodesk или Oracle. AutoCAD Mobile / Primavera требуют собственных прав доступа и лицензий.</p></section>`;if(PRODUCT_MODE==='cad')document.querySelectorAll('[data-go=\"p6\"],[data-go=\"schedule\"]').forEach(x=>x.remove());if(PRODUCT_MODE==='p6')document.querySelectorAll('[data-go=\"cad\"],[data-go=\"drawing\"]').forEach(x=>x.remove())}\nfunction course(id){if(PRODUCT_MODE!=='all'&&id!==PRODUCT_MODE)return home();state.course=id;let a=days(id),c=a.filter(x=>completed[id+x.day]).length;$('#view').innerHTML=`<section class=\"card\"><h2>${id==='cad'?'AutoCAD · 21 день':'Primavera P6 · 14 дней'}</h2><p class=\"muted\">${id==='cad'?'Мобильная адаптация курса по исполнительной документации':'Полный текст 14-дневного курса P6 Professional с мобильными тренировками'}</p><div class=\"bar\"><div style=\"width:${Math.round(c/a.length*100)}%\"></div></div><p>${c} из ${a.length} дней завершено</p></section><section class=\"days\">${a.map(x=>`<button class=\"day ${completed[id+x.day]?'done':''}\" data-lesson=\"${id}:${x.day}\"><strong>${completed[id+x.day]?'✓ ':''}День ${x.day}</strong><small>${esc(x.title)}</small></button>`).join('')}</section>`;}\nfunction lesson(){let a=days(state.course),x=a.find(l=>l.day===state.day);if(!x){state.section=state.course;return render()};let value=completed[state.course+x.day];$('#view').innerHTML=`<div class=\"row\" style=\"margin-bottom:12px\"><button class=\"btn soft\" data-go=\"${state.course}\">← К дням</button><span class=\"pill\">День ${x.day}/${a.length}</span></div><section class=\"card\"><h2>${esc(x.title)}</h2><p>${esc(x.goal)}</p>${state.course==='p6'?`<p class=\"notice\">${esc(x.phoneTip)}</p><details><summary>Полный материал урока · читать</summary><pre>${esc(x.full)}</pre></details>`:`<h3>Что важно понять</h3><p>${esc(x.concept)}</p><h3>Практика на телефоне</h3><p>${esc(x.explanation)}</p><p>${esc(x.mobileSteps)}</p><h3>Контрольный результат</h3><p>${esc(x.deliverable)}</p><div class=\"notice\">Частая ошибка: ${esc(x.pitfall)}. Возможности Autodesk AutoCAD Mobile могут отличаться от Windows.</div>`}<div class=\"row\"><button class=\"btn outline\" data-go=\"${state.course==='cad'?'drawing':'schedule'}\">Открыть учебный инструмент</button><button class=\"btn soft\" data-action=\"speak\">Прослушать</button></div></section><section class=\"card\"><h2>Проверка урока</h2><p>${esc(x.challenge)}</p><input id=\"checkanswer\" class=\"field\" placeholder=\"${x.answerType==='number'?'Введите результат числом':'Запишите краткий ответ'}\" inputmode=\"${x.answerType==='number'?'decimal':'text'}\"><div class=\"row\"><button class=\"btn\" data-action=\"check\">Проверить</button><button class=\"btn soft\" data-action=\"showAnswer\">Показать разбор</button></div><div id=\"feedback\" style=\"margin:12px 0\"></div><button class=\"btn outline full\" data-action=\"done\">${value?'✓ Урок пройден · подтвердить':'Отметить выполнение практики'}</button><p class=\"muted\">Отметка урока означает самостоятельное выполнение. Знание программы не подтверждается официальным сертификатом.</p></section>`;}\nfunction check(){let x=days(state.course).find(l=>l.day===state.day),u=$('#checkanswer').value.trim();let answer=x.answer;let okay=x.answerType==='number'?u!==''&&Math.abs(Number(u.replace(',','.'))-Number(answer))<.03:u.length>5;$('#feedback').innerHTML=`<div class=\"${okay?'success':'error'}\">${okay?'Ответ принят для учебного упражнения.':'Нужно ещё проверить решение или прочитать разбор.'}</div>${x.answerType==='text'?'Для текстового вопроса здесь проверяется только заполнение ответа. Содержание сравните с эталоном; автоматическая смысловая проверка не выполняется.':''}`;}\nfunction showAnswer(){let x=days(state.course).find(l=>l.day===state.day);$('#feedback').innerHTML=`<div class=\"notice\">Учебный эталон: <b>${esc(x.answer)}</b></div>`}\nfunction done(){completed[state.course+state.day]=true;save();let d=state.day;state.day=Math.min(days(state.course).length,d+1);render()}\nfunction speak(){let x=days(state.course).find(l=>l.day===state.day);if(!('speechSynthesis'in window))return alert('На этом устройстве синтез речи не поддерживается');speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance([x.title,x.goal,x.explanation||x.full?.slice(0,1200)||''].join('. '));utterance.lang='ru-RU';speechSynthesis.speak(utterance)}\n// Coordinate-based educational drawing (not DWG editor)\nlet cad={scale:1,ox:0,oy:0,tool:'pan',layers:{project:true,fact:true,point:true},points:[],drag:null};\nfunction drawing(){let key='cad';$('#view').innerHTML=`<section class=\"card\"><h2>CAD-полигон · РВС-5000</h2><p class=\"muted\">Проект: (60000;45000) мм · факт: (60018;44988) мм. Схема намеренно увеличивает отклонение, чтобы его было видно.</p><div class=\"row tools\"><button data-cad=\"pan\">Перемещение</button><button data-cad=\"point\">Точка</button><button data-cad=\"measure\">Измерение</button><button data-cad=\"zoom+\">＋</button><button data-cad=\"zoom-\">－</button><button data-cad=\"reset\">Сброс</button></div><p><label><input id=\"cadproject\" type=\"checkbox\" checked> Проект</label> · <label><input id=\"cadfact\" type=\"checkbox\" checked> Факт</label></p><canvas id=\"cad\" width=\"800\" height=\"500\" aria-label=\"Схема площадки РВС-5000\"></canvas><p id=\"cadout\" class=\"notice\">Касание с выбранным инструментом.</p><div class=\"row\"><button class=\"btn outline\" data-action=\"cadexport\">Экспорт точек DXF</button><button class=\"btn soft\" data-action=\"cadreport\">Скачать отчёт</button></div></section>`;paintCad();}\nfunction cv(){return $('#cad')?.getContext('2d')}const tx=(x,w)=>w/2+(x-60000)/350*cad.scale+cad.ox,ty=(y,h)=>h/2-(y-45000)/350*cad.scale+cad.oy;\nfunction paintCad(){const ctx=cv();if(!ctx)return;const w=800,h=500;ctx.clearRect(0,0,w,h);ctx.fillStyle='#fbfdff';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#e6edf4';for(let i=0;i<w;i+=40){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,h);ctx.stroke()}for(let j=0;j<h;j+=40){ctx.beginPath();ctx.moveTo(0,j);ctx.lineTo(w,j);ctx.stroke()}function ring(x,y,r,col){ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(tx(x,w),ty(y,h),r/350*cad.scale,r/350*cad.scale,0,0,2*Math.PI);ctx.stroke()}\nif(cad.layers.project){ring(60000,45000,12000,'#346ce8');ring(60000,45000,11000,'#4e7ef2');ctx.fillStyle='#346ce8';ctx.fillText('Проект: 60000, 45000',20,26)}if(cad.layers.fact){ring(60018+700,44988-450,12007,'#e38432');ctx.fillStyle='#9f5700';ctx.fillText('Факт: +18 / -12 мм (графически увеличено)',20,47)}ctx.fillStyle='#1e855e';for(let p of cad.points){ctx.beginPath();ctx.arc(tx(p.x,w),ty(p.y,h),4,0,7);ctx.fill()}ctx.font='17px system-ui';ctx.fillStyle='#435875';ctx.fillText('Учебный чертёж · не геодезическая основа',20,h-18)}\nfunction cadInteraction(evt){if(!$('#cad'))return;const rect=$('#cad').getBoundingClientRect();let px=(evt.clientX-rect.left)*800/rect.width,py=(evt.clientY-rect.top)*500/rect.height;let x=60000+((px-400-cad.ox)*350/cad.scale),y=45000-((py-250-cad.oy)*350/cad.scale);if(cad.tool==='point'){cad.points.push({x:Math.round(x),y:Math.round(y)});$('#cadout').textContent='Добавлена точка ('+Math.round(x)+'; '+Math.round(y)+') мм'}else if(cad.tool==='measure'){let p=cad.measure;if(!p){cad.measure={x,y};$('#cadout').textContent='Выберите вторую точку'}else{let dist=Math.hypot(x-p.x,y-p.y);$('#cadout').textContent='Учебная длина: '+dist.toFixed(1)+' мм';cad.measure=null}}paintCad()}\nfunction fileDownload(name,content,mime){const blob=new Blob([content],{type:mime||'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}\nfunction cadExport(){let lines=['0','SECTION','2','ENTITIES'];for(const p of cad.points){lines.push('0','POINT','8','IZN_USER_POINTS','10',String(p.x),'20',String(p.y),'30','0')}lines.push('0','ENDSEC','0','EOF');fileDownload('IZN_учебные_точки.dxf',lines.join('\\n'),'application/dxf')}\n// Editable, mathematically validated basic CPM in working-day units, NOT a full P6 scheduler.\nlet jobs=[{id:'ENG',name:'Проектирование',d:4,p:''},{id:'PRC',name:'Поставка',d:7,p:'ENG'},{id:'CIV',name:'Основание',d:6,p:'ENG'},{id:'MEC',name:'Монтаж',d:5,p:'PRC,CIV'},{id:'TST',name:'Испытания',d:3,p:'MEC'}];let baseline=null;\nfunction cpm(input=jobs){const dict=Object.fromEntries(input.map(x=>[x.id,{...x,prev:x.p.split(',').map(t=>t.trim()).filter(Boolean),ES:0,EF:0,LS:0,LF:0,TF:0}]));if(Object.keys(dict).length!==input.length)throw Error('Повтор Activity ID.');for(const x of Object.values(dict))for(const p of x.prev)if(!dict[p])throw Error('Неизвестная предшествующая операция: '+p);let order=[],seen=new Set();while(order.length<input.length){let ready=Object.values(dict).filter(x=>!seen.has(x.id)&&x.prev.every(p=>seen.has(p)));if(!ready.length)throw Error('Цикл в связях — исправьте предшественников');for(const x of ready){x.ES=x.prev.length?Math.max(...x.prev.map(p=>dict[p].EF)):0;x.EF=x.ES+x.d;if(!(x.d>=0&&Number.isFinite(x.d)))throw Error('Длительность должна быть неотрицательной');order.push(x);seen.add(x.id)}}let duration=Math.max(...order.map(x=>x.EF));for(let i=order.length-1;i>=0;i--){let x=order[i],succ=order.filter(s=>s.prev.includes(x.id));x.LF=succ.length?Math.min(...succ.map(s=>s.LS)):duration;x.LS=x.LF-x.d;x.TF=x.LS-x.ES}return {order,duration}}\nfunction schedule(){let out;try{out=cpm()}catch(e){out={error:e.message}}$('#view').innerHTML=`<section class=\"card\"><h2>CPM-лаборатория · критический путь</h2><p class=\"muted\">Редактируйте длительности и предшественников FS, пересчитывайте ранние и поздние сроки и резервы. Это учебная модель с единым условным календарём, не Oracle P6.</p><div class=\"scroll\"><table><thead><tr><th>ID</th><th>Работа</th><th>Дней</th><th>Предш.</th><th>ES</th><th>EF</th><th>TF</th></tr></thead><tbody>${jobs.map((j,i)=>`<tr><td>${esc(j.id)}</td><td>${esc(j.name)}</td><td><input data-job=\"${i}\" data-key=\"d\" type=\"number\" min=\"0\" step=\"1\" value=\"${j.d}\" style=\"width:60px\"></td><td><input data-job=\"${i}\" data-key=\"p\" value=\"${esc(j.p)}\" style=\"width:90px\"></td><td>${out.error?'—':out.order.find(x=>x.id===j.id).ES}</td><td>${out.error?'—':out.order.find(x=>x.id===j.id).EF}</td><td>${out.error?'—':out.order.find(x=>x.id===j.id).TF}</td></tr>`).join('')}</tbody></table></div><p class=\"${out.error?'error':'success'}\">${out.error?esc(out.error):'Длительность проекта: '+out.duration+' раб. дней · Критические работы: '+out.order.filter(x=>x.TF===0).map(x=>x.id).join(' → ')}</p><div class=\"row\"><button class=\"btn\" data-action=\"calc\">Пересчитать</button><button class=\"btn outline\" data-action=\"baseline\">Зафиксировать baseline</button><button class=\"btn soft\" data-action=\"report\">Отчёт</button></div>${baseline!==null?`<p class=\"notice\">Baseline: ${baseline} дней. Отклонение нового прогноза: ${out.error?'—':out.duration-baseline} дней.</p>`:''}</section>`}\nfunction updateJobs(){document.querySelectorAll('[data-job]').forEach(n=>{let j=jobs[Number(n.dataset.job)];j[n.dataset.key]=n.dataset.key==='d'?Number(n.value):n.value.toUpperCase().trim()})}\nfunction report(){let r;try{r=cpm()}catch(e){return alert(e.message)}fileDownload('RVS5000_CPM_отчёт.csv',['ID;Работа;Дней;Предшественники;ES;EF;LS;LF;TF',...r.order.map(x=>[x.id,x.name,x.d,x.prev.join(','),x.ES,x.EF,x.LS,x.LF,x.TF].join(';'))].join('\\n'),'text/csv;charset=utf-8')}\ndocument.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let go=b.dataset.go,les=b.dataset.lesson,action=b.dataset.action,mode=b.dataset.cad;if(go){state.section=go;render();scrollTo(0,0)}if(les){let[id,day]=les.split(':');state={section:'lesson',course:id,day:Number(day)};render();scrollTo(0,0)}if(mode){if(mode==='zoom+')cad.scale*=1.3;else if(mode==='zoom-')cad.scale/=1.3;else if(mode==='reset')cad={scale:1,ox:0,oy:0,tool:'pan',layers:{project:true,fact:true,point:true},points:[]};else cad.tool=mode;paintCad()}if(action==='check')check();if(action==='showAnswer')showAnswer();if(action==='done')done();if(action==='speak')speak();if(action==='cadexport')cadExport();if(action==='cadreport')fileDownload('RVS5000_измерения.txt',`Проект: X=60000 Y=45000 мм\\nФакт: X=60018 Y=44988 мм\\nСмещение: 21.63 мм\\nСозданные точки: ${JSON.stringify(cad.points)}`);if(action==='calc'){updateJobs();schedule()}if(action==='baseline'){updateJobs();try{baseline=cpm().duration;schedule()}catch(e){alert(e.message)}}if(action==='report'){updateJobs();report()}});\ndocument.addEventListener('change',e=>{if(e.target.id==='cadproject'){cad.layers.project=e.target.checked;paintCad()}if(e.target.id==='cadfact'){cad.layers.fact=e.target.checked;paintCad()}});\ndocument.addEventListener('pointerdown',e=>{if(e.target.id!=='cad')return;if(cad.tool!=='pan')return;cad.drag={x:e.clientX,y:e.clientY,ox:cad.ox,oy:cad.oy};e.target.setPointerCapture(e.pointerId)});\ndocument.addEventListener('pointermove',e=>{if(e.target.id!=='cad'||!cad.drag)return;const r=$('#cad').getBoundingClientRect();cad.ox=cad.drag.ox+(e.clientX-cad.drag.x)*800/r.width;cad.oy=cad.drag.oy+(e.clientY-cad.drag.y)*500/r.height;paintCad()});\ndocument.addEventListener('pointerup',e=>{if(e.target.id!=='cad')return;if(cad.drag){cad.drag=null;return}cadInteraction(e)});render();\n</script></body></html>"});
